override def isEmpty(i: Int, j: Int): Boolean = {
    decompressPixelExists
    !BitArray.isBitSet(pixelExists, pixelOffset(i, j))
  }

override def getPixelValue(i: Int, j: Int): T = {
    decompressPixelData
    val offset = pixelOffset(i, j) * bytesPerPixel
    if (numComponents == 1)
      valueReader(pixelData, offset)
    else {
      val value: Array[_] = pixelValueTemplate.asInstanceOf[Array[_]].clone()
      for (i <- 0 until numComponents) {
        java.lang.reflect.Array.set(value, i, valueReader(pixelData, offset + i * componentType.defaultSize))
      }
      value.asInstanceOf[T]
    }
  }

override def schema: StructType = {
    var attributes = Seq(StructField("tileID", IntegerType, false),
      StructField("mapLocator", RasterMetadataType, false),
      StructField("imageValues", ArrayType.apply(pixelType)))
    if (rasterFeature != null)
      attributes = attributes ++ rasterFeature.schema
    StructType(attributes)
  }

def getPointValue(x: Double, y: Double): T = {
    val pixel: Point2D.Double = new Point2D.Double()
    rasterMetadata.modelToGrid(x, y, pixel)
    getPixelValue(pixel.x.toInt, pixel.y.toInt)
  }

def isEmptyAt(x: Double, y: Double): Boolean = {
    val pixel: Point2D.Double = new Point2D.Double()
    rasterMetadata.modelToGrid(x, y, pixel)
    isEmpty(pixel.x.toInt, pixel.y.toInt)
  }

def extents: Geometry = {
    val values = Array[Double](x1, y1, x2+1, y1, x2+1, y2+1, x1, y2+1, x1, y1)
    rasterMetadata.g2m.transform(values, 0, values, 0, 5)
    val coords = new Array[Coordinate](values.length / 2)
    for (i <- values.indices by 2) {
      coords(i / 2) = new CoordinateXY(values(i), values(i+1))
    }
    val polygon = GeometryReader.DefaultGeometryFactory.createPolygon(coords)
    polygon.setSRID(rasterMetadata.srid)
    polygon
  }

override def get(i: Int): Any = i match {
    case 0 => java.lang.Integer.valueOf(tileID)
    case 1 => ITile.rasterMetadataToRow(rasterMetadata)
    case 2 => getImageValues
    case x => rasterFeature.get(x - 3)
  }

def setAttribute(name: String, value: Any): ITile[T] = {
    val thisTile: ITile[T] = this
    val newRasterFeature = this.rasterFeature.setOrAppend(name, value)
    // Return a delegate tile that replaces the RasterFeature and keeps everything else intact
    new ITile[T](this.tileID, this.rasterMetadata, newRasterFeature) {
      override def getPixelValue(i: Int, j: Int): T = thisTile.getPixelValue(i, j)
      override def isEmpty(i: Int, j: Int): Boolean = thisTile.isEmpty(i, j)
      override def numComponents: Int = thisTile.numComponents
      override def componentType: DataType = thisTile.componentType
      override def copy(): Row = thisTile.copy()
    }
  }

def rasterMetadataToRow(metadata: RasterMetadata): Row = {
    val g2m_array = new Array[Double](6)
    metadata.g2m.getMatrix(g2m_array)
    new GenericRowWithSchema(Array(metadata.x1, metadata.y1, metadata.x2, metadata.y2,
      metadata.tileWidth, metadata.tileHeight, metadata.srid, g2m_array.toSeq), RasterMetadataType.sqlType)
  }

override def write(kryo: Kryo, output: Output, tile: ITile[T]): Unit = {
    // A general method to write any tile
    // Write tile identifier and metadata
    output.writeInt(tile.tileID)
    kryo.writeObject(output, tile.rasterMetadata)
    kryo.writeObject(output, tile.rasterFeature)
    // Write pixel type and number of components
    output.writeInt(tile.numComponents)
    output.writeInt(sparkTypeToNumber(tile.componentType))
    val bytesPerPixel = tile.componentType.defaultSize * tile.numComponents
    // Write pixel data
    val pixelExists = new Array[Byte]((tile.tileWidth * tile.tileHeight + 7) / 8)

    val dummyData: Array[Byte] = Array.fill[Byte](bytesPerPixel)(0)
    val baos2 = new ByteArrayOutputStream()
    val zos2 = new LZWOutputStream(baos2)
    val pixelData = new DataOutputStream(zos2)
    val dataWriter: (DataOutputStream, T) => Unit = if (tile.numComponents == 1)
      ITileSerializer.dataWriters(sparkTypeToNumber(tile.componentType)).asInstanceOf[(DataOutputStream, T) => Unit]
    else
      ITileSerializer.dataWriters(0x10 | sparkTypeToNumber(tile.componentType)).asInstanceOf[(DataOutputStream, T) => Unit]

    var i = 0
    for (y <- tile.y1 to tile.y2; x <- tile.x1 to tile.x2) {
      if (tile.isDefined(x, y)) {
        BitArray.setBit(pixelExists, i)
        dataWriter(pixelData, tile.getPixelValue(x, y))
      } else {
        pixelData.write(dummyData)
      }
      i += 1
    }

    pixelData.close()

    val data1 = LZWCodec.encode(pixelExists)
    output.writeInt(data1.length)
    output.write(data1)
    val data2 = baos2.toByteArray
    output.writeInt(data2.length)
    output.write(data2)
  }

def setOrAppend(attr: String, value: Any): RasterFeature = {
    try {
      val existingAttribute = this.schema.fieldIndex(attr)
      val values = this.toSeq.toArray
      values(existingAttribute) = value
      new RasterFeature(values, this.schema)
    } catch {
      case _: IllegalArgumentException =>
        RasterFeature.append(this, attr, value)
    }
  }

def append(rasterFeature: RasterFeature, name: String, value: Any): RasterFeature  = {
    val values: Seq[Any] = Row.unapplySeq(rasterFeature).get :+ value
    val schema: Seq[StructField] = rasterFeature.schema :+ StructField(name, RasterSchemaHelper.detectType(value))
    new RasterFeature(values.toArray, StructType(schema))
  }

override def write(kryo: Kryo, output: Output, rasterFeature: RasterFeature): Unit = {
    RasterSchemaHelper.write(rasterFeature.schema, kryo, output)
    kryo.writeClassAndObject(output, rasterFeature.getValues)
  }

override def read(kryo: Kryo, input: Input, klass: Class[RasterFeature]): RasterFeature = {
    val schema = RasterSchemaHelper.readIn(kryo, input)
    val values = kryo.readClassAndObject(input).asInstanceOf[Array[Any]]
    new RasterFeature(values, schema)
  }

def getTileIDAtPixel(iPixel: Int, jPixel: Int): Int = {
    val iTile = (iPixel - x1) / tileWidth
    val jTile = (jPixel - y1) / tileHeight
    jTile * numTilesX + iTile
  }

def getTileIDAtPoint(x: Double, y: Double): Int = {
    val pixel: Point2D.Double = new Point2D.Double()
    modelToGrid(x, y, pixel)
    getTileIDAtPixel(pixel.x.toInt, pixel.y.toInt)
  }

def getTileX1(tileID: Int): Int = {
    val iTile = tileID % numTilesX
    x1 + iTile * tileWidth
  }

def getTileX2(tileID: Int): Int = {
    val iTile = tileID % numTilesX
    (x1 + (iTile + 1) * tileWidth - 1) min (x2 - 1)
  }

def getTileY1(tileID: Int): Int = {
    val iTile = tileID / numTilesX
    y1 + iTile * tileHeight
  }

def getTileY2(tileID: Int): Int = {
    val iTile = tileID / numTilesX
    (y1 + (iTile + 1) * tileHeight - 1) min (y2 - 1)
  }

def gridToModel(i: Double, j: Double, outPoint: Point2D.Double): Unit = {
    outPoint.setLocation(i, j)
    g2m.transform(outPoint, outPoint)
  }

def modelToGrid(x: Double, y: Double, outPoint: Point2D.Double): Unit = {
    outPoint.setLocation(x, y)
    g2m.inverseTransform(outPoint, outPoint)
  }

def envelope: Envelope = {
    val bounds = Array[Double](x1, y1, x2, y2)
    g2m.transform(bounds, 0, bounds, 0, 2)
    new Envelope(bounds(0) min bounds(2), bounds(0) max bounds(2),
      bounds(1) min bounds(3), bounds(1) max bounds(3))
  }

def extents: Geometry = {
    val values = Array[Double](x1, y1, x2, y1, x2, y2, x1, y2, x1, y1)
    g2m.transform(values, 0, values, 0, 5)
    val coords = new Array[Coordinate](values.length / 2)
    for (i <- values.indices by 2) {
      coords(i / 2) = new CoordinateXY(values(i), values(i+1))
    }
    val polygon = GeometryReader.DefaultGeometryFactory.createPolygon(coords)
    polygon.setSRID(this.srid)
    polygon
  }

override def hashCode(): Int = {
    x1.hashCode() + x2.hashCode() + y1.hashCode() + y2.hashCode() + tileWidth.hashCode() + tileHeight.hashCode() +
      srid.hashCode() + g2m.hashCode()
  }

override def toString: String = {
    s"RasterMetadata ($x1, $y1)-($x2, $y2) tile size ${tileWidth}X${tileHeight} SRID: $srid G2M: $g2m"
  }

def rescale(newRasterWidth: Int, newRasterHeight: Int): RasterMetadata = {
    // 1. Set (x1, y1) = (0, 0) for the new raster metadata
    // 2. Set (x2, y2) = (newRasterWidth, newRasterHeight) for the new raster metadata
    // 3. Use the same SRID
    // 4. Adjust grid-to-model to make (x1, y1) point to the first corner and (x2, y2) to the other corner
    val corners = Array[Double](x1, y1, x2, y2)
    this.g2m.transform(corners, 0, corners, 0, 2)
    RasterMetadata.create(corners(0), corners(1), corners(2), corners(3), this.srid, newRasterWidth, newRasterHeight,
      this.tileWidth min newRasterWidth, this.tileHeight min newRasterHeight)
  }

def reproject(targetCRS: CoordinateReferenceSystem): RasterMetadata = {
    val corners = Array[Double](x1, y1, x2, y2)
    g2m.transform(corners, 0, corners, 0, 2)
    val targetSRID = CRSServer.crsToSRID(targetCRS)
    try {
      Reprojector.reprojectEnvelopeInPlace(corners, this.srid, targetSRID)
    } catch {
      case _: ProjectionException =>
        // This problem might happen if the range of the source goes outside the range of the destination
        // For example, if we are trying to reproject the entire space from EPSG:4326 to web-mercator (EPSG:3857)
        // To fix this problem, we project the entire target space back to the source and compute the intersection
        val targetReversed: Boolean = CRS.getAxisOrder(targetCRS) == AxisOrder.NORTH_EAST
        val targetDomainCorners = if (targetSRID == 3857) {
          // The code in the else block is supposed to work for any CRS but the extents are not accurate
          // At least for the EPSG:3857. So we do it manually since this is a popular one for visualization and
          // we do not want to mess it up
          val maxLatitude = (2 * Math.atan(Math.exp(Math.PI)) - Math.PI / 2) * 180.0 / Math.PI
          if (!targetReversed)
            Array[Double](-180, maxLatitude, 180, -maxLatitude)
          else
            Array[Double](maxLatitude, -180, -maxLatitude, 180)
        } else {
          val geographicExtents = targetCRS.getDomainOfValidity.getGeographicElements.toArray()(0).asInstanceOf[GeographicBoundingBox]
          val targetDomainCorners = new Array[Double](4)
          targetDomainCorners(0) = geographicExtents.getWestBoundLongitude
          targetDomainCorners(1) = geographicExtents.getNorthBoundLatitude
          targetDomainCorners(2) = geographicExtents.getEastBoundLongitude
          targetDomainCorners(3) = geographicExtents.getSouthBoundLatitude
          Reprojector.reprojectEnvelopeInPlace(targetDomainCorners, 4326, this.srid)
          targetDomainCorners
        }
        // Compute the intersection
        corners(0) = x1
        corners(1) = y1
        corners(2) = x2
        corners(3) = y2
        g2m.transform(corners, 0, corners, 0, 2)
        corners(0) = corners(0) max targetDomainCorners(0)
        corners(1) = corners(1) min targetDomainCorners(1)
        corners(2) = corners(2) min targetDomainCorners(2)
        corners(3) = corners(3) max targetDomainCorners(3)
        // Project back the intersected area only
        Reprojector.reprojectEnvelopeInPlace(corners, this.srid, targetSRID)
    }
    RasterMetadata.create(corners(0), corners(1), corners(2), corners(3), targetSRID,
      this.rasterWidth, this.rasterHeight, this.tileWidth, this.tileHeight)
  }

def create(x1: Double, y1:Double, x2: Double, y2:Double, srid: Int,
             rasterWidth: Int, rasterHeight: Int, tileWidth: Int, tileHeight: Int): RasterMetadata = {
    val g2m = new AffineTransform()
    g2m.translate(x1, y1)
    g2m.scale((x2 - x1) / rasterWidth, (y2 - y1) / rasterHeight)
    new RasterMetadata(0, 0, rasterWidth, rasterHeight, tileWidth, tileHeight, srid, g2m)
  }

def allMetadata[T](raster: RDD[ITile[T]]): Array[RasterMetadata] =
    // For efficiency, we assume that all metadata in each partition is the same
    raster.mapPartitions(tiles => {
        if (tiles.hasNext) {
          Some(tiles.next().rasterMetadata).iterator
        } else {
          Option.empty[RasterMetadata].iterator
        }
      }).distinct()
      .collect()

def gridToGridTransform(sourceMetadata: RasterMetadata, targetMetadata: RasterMetadata): MathTransform = {
    val sourceG2M: MathTransform = new AffineTransform2D(sourceMetadata.g2m)
    val sourceM2TargetM: MathTransform = Reprojector.findTransformationInfo(sourceMetadata.srid, targetMetadata.srid).mathTransform
    val targetM2G: MathTransform = new AffineTransform2D(targetMetadata.g2m).inverse()
    ConcatenatedTransform.create(ConcatenatedTransform.create(sourceG2M, sourceM2TargetM), targetM2G)
  }

def writeExternalObj(schema:StructType, out: ObjectOutput): Unit = {
    // Number of attributes
    out.writeShort(schema.length)
    if (schema.length > 0) {
      // Attribute names
      for (field <- schema)
        out.writeUTF(if (field.name == null) "" else field.name)
      // Attribute types
      for (field <- schema)
        writeType(field.dataType, out)
    }
  }

def readExternalObj(in: ObjectInput): StructType = {
    // Read number of attributes
    val recordLength: Int = in.readShort()
    val attributeNames = new Array[String](recordLength)
    val attributeTypes = new Array[DataType](recordLength)
    // Read attribute names
    for (i <- 0 until recordLength)
      attributeNames(i) = in.readUTF()
    // Read attribute types
    for (i <- 0 until recordLength)
      attributeTypes(i) = readType(in)
    val _schema = StructType((0 until recordLength).map(i => StructField(attributeNames(i), attributeTypes(i))))
    _schema
  }

def readType(in: ObjectInput): DataType = {
    val typeOrdinal = in.readByte()
    if (typeOrdinal == 11) {
      // Indicates a map type
      val keyType: DataType = readType(in)
      val valueType: DataType = readType(in)
      MapType(keyType, valueType, valueContainsNull = true)
    } else if (typeOrdinal == 12) {
      // Indicates an array type
      val elementType: DataType = readType(in)
      ArrayType(elementType, containsNull = true)
    } else {
      ordinalTypes.getOrElse(typeOrdinal, BinaryType)
    }
  }

tileID: Int, private[raptor] val tiffTile: AbstractTiffTile,
                                      private[raptor] val fillValue: Int, private[raptor] val pixelBitMask: Array[Byte],
                                      metadata: RasterMetadata, rasterFeatures: RasterFeature

override def isEmpty(i: Int, j: Int): Boolean = {
    if (pixelBitMask != null) {
      val pixelLocation = (j - y1) * tileWidth + (i - x1)
      val byteIndex = pixelLocation >> 3
      val bitOffset = pixelLocation & 7
      (pixelBitMask(byteIndex) & (0x80.toByte >>> bitOffset)) == 0
    } else {
      for (c <- 0 until numComponents) {
        if (tiffTile.getSampleValueAsInt(i, j, c) == fillValue)
          return true
      }
      false
    }
  }

def moveToNextIntersections: Unit = {
    if (intersections.hasNext) {
      val nextValue = intersections.next()
      currentFileTileID = nextValue._1
      currentIntersections = nextValue._2
      assert(!currentIntersections.tileID.isEmpty, "Intersections cannot be empty")
      ys = currentIntersections.ys.iterator()
      xs = currentIntersections.xs.iterator()
      geometryIndexes = currentIntersections.geometryIndexes.iterator()
    }
  }

override def next(): (Long, PixelRange) = {
    val geometryID = geometryIndexes.next().toInt
    val y = ys.next().toInt
    val x1 = xs.next().toInt
    val x2 = xs.next().toInt
    val returnValue = (currentFileTileID, PixelRange(currentIntersections.featureIDs(geometryID), y, x1, x2))
    if (!xs.hasNext)
      moveToNextIntersections
    returnValue
  }

def moveToNextIntersections: Unit = {
    // Jump to the next file with non-empty intersections
    while (intersections.hasNext && (currentIntersections == null || currentIntersections.getNumIntersections == 0)) {
      val n = intersections.next()
      metadataID = n._1
      currentIntersections = n._2
    }
    if (currentIntersections != null && currentIntersections.getNumIntersections > 0)
      i = 0
  }

override def next(): (Long, CompactIntersections) = {
    val firstRange: Int = i
    val tileID = currentIntersections.getTileID(i)
    do {
      i += 1
    } while (i < currentIntersections.getNumIntersections && currentIntersections.getTileID(i) == tileID)
    val ys = CompactLongArray.constructLongArray(currentIntersections.ys, firstRange, i)
    val xs = CompactLongArray.constructLongArray(currentIntersections.xs, 2 * firstRange, 2 * i)
    val tileIDs = CompactLongArray.constructLongArray(currentIntersections.tileID, firstRange, i)
    val geometryIndexes = CompactLongArray.constructLongArray(currentIntersections.polygonIndexes, firstRange, i)
    val compactIntersections = new CompactIntersections(tileIDs, ys, xs, geometryIndexes, currentIntersections.featureIDs)
    val metadataTileID: Long = (metadataID << 32) | tileID

    // Move to the next intersections, if needed
    if (i >= currentIntersections.getNumIntersections) {
      currentIntersections = null
      moveToNextIntersections
    }
    (metadataTileID, compactIntersections)
  }

def merge(other: AbstractConvolutionTile[T]): AbstractConvolutionTile[T] = {
    if (this.tileID != sourceTileID) {
      // This is a partial tile, need to create a full tile
      val fullTile: AbstractConvolutionTile[T] = if (numComponents == 1)
        new ConvolutionTileSingleBand(this.tileID, this.metadata, this.rasterFeature, this.w, this.weights, this.tileID).asInstanceOf[AbstractConvolutionTile[T]]
      else
        new ConvolutionTileMultiBand(this.tileID, this.metadata, this.rasterFeature, this.numComponents, this.w, this.weights, this.tileID).asInstanceOf[AbstractConvolutionTile[T]]
      fullTile.merge(this)
      fullTile.merge(other)
      fullTile
    } else if (other.tileID != other.sourceTileID) {
      for (x <- (this.x1 max other.x1) to (this.x2 min other.x2); y <- (this.y1 max other.y1) to (this.y2 min other.y2); if other.isDefined(x, y))
        updatePixel(x, y, 1.0f, other.getPixelValue(x, y))
      this
    } else {
      for (i <- 0 until pixelValues.length)
        pixelValues(i) += other.pixelValues(i)
      this.pixelExists.inplaceOr(other.pixelExists)
      this
    }
  }

tileID: Int, metadata: RasterMetadata, rasterFeature: RasterFeature, w: Int, weights: Array[Float],
                                stid: Int,
                               @transient val values: Array[Float] = null, @transient val exists: BitArray = null

tileID: Int, metadata: RasterMetadata, rasterFeature: RasterFeature,
                               override val numComponents: Int,
                               w: Int, weights: Array[Float], stid: Int,
                               @transient val values: Array[Float] = null,
                               @transient val exists: BitArray = null

override def getPixelValue(i: Int, j: Int): Array[Float] = {
    val x = new Array[Float](numComponents)
    val offset = pixelOffset(i, j)
    for (b <- 0 until numComponents)
      x(b) = pixelValues(offset + b)
    x
  }

override def isEmpty(i: Int, j: Int): Boolean = {
    tile.isEmpty(i, j) || !filter(tile.getPixelValue(i, j))
  }

def this(filename: String) {
    this()
    val fileSystem = new Path(filename).getFileSystem(new Configuration())
    initialize(fileSystem, filename, "0", new BeastOptions())
  }

override def initialize(fileSystem: FileSystem, path: String, layer: String, opts: BeastOptions): Unit = {
    super.initialize(fileSystem, path, layer, opts)
    val iLayer = layer.toInt
    this.initialize(fileSystem, new Path(path), iLayer)
    if (opts.contains("fillvalue")) {
      // Override the fill value in case it is not appropriately written in the file
      this.fillValue = opts.getInt("fillvalue", -1)
    }
  }

override def readTile(tileID: Int): ITile[T] = {
    val tiffTile: AbstractTiffTile = tiffDataRaster.getTile(tileID)
    val pixelExists: Array[Byte] = if (tiffMaskRaster != null) {
      // We assume that both the data and mask layers are co-tiled
      val tiffMaskTile = tiffMaskRaster.getTile(tileID)
      assert(tiffMaskTile.getTileData.length == 1, "Unsupported PlanarFormat for mask")
      tiffMaskTile.getTileData()(0)
    } else {
      null
    }
    if (tiffTile.getNumSamples == 1) {
      tiffTile.getSampleFormat(0) match {
        case 1 | 2 => new GeoTiffTileInt(tileID, tiffTile, fillValue, pixelExists, rasterMetadata, rasterFeature).asInstanceOf[ITile[T]]
        case 3 if tiffTile.getBitsPerSample(0) == 32 => new GeoTiffTileFloat(tileID, tiffTile, fillValue, pixelExists, rasterMetadata, rasterFeature).asInstanceOf[ITile[T]]
        case 3 if tiffTile.getBitsPerSample(0) == 64 => new GeoTiffTileDouble(tileID, tiffTile, fillValue, pixelExists, rasterMetadata, rasterFeature).asInstanceOf[ITile[T]]
      }
    } else {
      // Assume that all samples have the same type
      tiffTile.getSampleFormat(0) match {
        case 1 | 2 => new GeoTiffTileIntArray(tileID, tiffTile, fillValue, pixelExists, rasterMetadata, rasterFeature).asInstanceOf[ITile[T]]
        case 3 if tiffTile.getBitsPerSample(0) == 32 => new GeoTiffTileFloatArray(tileID, tiffTile, fillValue, pixelExists, rasterMetadata, rasterFeature).asInstanceOf[ITile[T]]
        case 3 if tiffTile.getBitsPerSample(0) == 64 => new GeoTiffTileDoubleArray(tileID, tiffTile, fillValue, pixelExists, rasterMetadata, rasterFeature).asInstanceOf[ITile[T]]
      }
    }
  }

override def close(): Unit = {
    if (tiffMaskReader != null) {
      tiffMaskReader.close()
    }
    if (tiffReader != null)
      tiffReader.close()
  }

def getSampleComponentType(sampleFormat: Int): DataType = {
    sampleFormat match {
      case TiffConstants.SAMPLE_IEEE_FLOAT => FloatType
      case TiffConstants.SAMPLE_SIGNED_INT => IntegerType
      case TiffConstants.SAMPLE_UNSIGNED_INT => IntegerType
      case TiffConstants.SAMPLE_UNDEFINED =>
      throw new RuntimeException(s"Unrecognized component type ")
    }
  }

def getRasterMetadata(fileSystem: FileSystem, path: Path): RasterMetadata = {
    val in = new BufferedFSDataInputStream(fileSystem.open(path), 4096)
    try {
      val tiffReader = ITiffReader.openFile(in)
      val tiffDataRaster = tiffReader.getLayer(0)
      // Define grid to model transformation (G2M)
      var buffer: ByteBuffer = null
      val g2m: AffineTransform = new AffineTransform
      var entry = tiffDataRaster.getEntry(ModelTiepointTag)
      if (entry != null) { // Translate point
        buffer = tiffReader.readEntry(entry, buffer)
        val dx = buffer.getDouble(3 * 8) - buffer.getDouble(0 * 8)
        val dy = buffer.getDouble(4 * 8) - buffer.getDouble(1 * 8)
        g2m.translate(dx, dy)
      }
      entry = tiffDataRaster.getEntry(ModelPixelScaleTag)
      if (entry != null) { // Scale point
        buffer = tiffReader.readEntry(entry, null)
        val sx = buffer.getDouble(0 * 8)
        val sy = buffer.getDouble(1 * 8)
        g2m.scale(sx, -sy)
      }

      // call to class to get metadata.
      val metadata = new GeoTiffMetadata(tiffReader, tiffDataRaster)
      val gtcs = new GeoTiffMetadata2CRSAdapter(null)
      val crs: CoordinateReferenceSystem = try {
        gtcs.createCoordinateSystem(metadata)
      } catch {
        case e: Exception =>
          null
      }
      // If CRS is not provided, assume EPSG:4326 instead of throwing an error of unknown geometry
      val srid = if (crs == null) 4326 else CRSServer.crsToSRID(crs)

      new RasterMetadata(0, 0, tiffDataRaster.getWidth, tiffDataRaster.getHeight,
        tiffDataRaster.getTileWidth, tiffDataRaster.getTileHeight, srid, g2m)
    } catch {
      case e: Exception =>
        throw new RuntimeException(s"Error opening file '$path'", e)
    } finally {
      in.close()
    }

  }

override def getPixelValue(i: Int, j: Int): Array[Double] = {
    val values = new Array[Double](numComponents)
    for (b <- values.indices)
      values(b) = tiffTile.getSampleValueAsDouble(i, j, b)
    values
  }

override def getPixelValue(i: Int, j: Int): Array[Float] = {
    val values = new Array[Float](numComponents)
    for (b <- values.indices)
      values(b) = tiffTile.getSampleValueAsFloat(i, j, b)
    values
  }

override def getPixelValue(i: Int, j: Int): Array[Int] = {
    val values = new Array[Int](numComponents)
    for (b <- values.indices)
      values(b) = tiffTile.getSampleValueAsInt(i, j, b)
    values
  }

override def write(kryo: Kryo, output: Output, tile: AbstractGeoTiffTile[T]): Unit = {
    // compress the underlying TiffTile first
    // Write the tiff tile
    kryo.writeObject(output, tile.tiffTile)
    // Write the geotiff information
    output.writeInt(tile.tileID)
    kryo.writeObject(output, tile.rasterMetadata)
    kryo.writeObject(output, tile.rasterFeature)
    output.writeInt(tile.fillValue)
    if (tile.pixelBitMask != null) {
      output.writeInt(tile.pixelBitMask.length)
      output.writeBytes(tile.pixelBitMask)
    } else {
      output.writeInt(0)
    }
  }

override def read(kryo: Kryo, input: Input, tileClass: Class[AbstractGeoTiffTile[T]]): AbstractGeoTiffTile[T] = {
    val tiffTile = kryo.readObject(input, classOf[AbstractTiffTile])
    val tileID = input.readInt()
    val metadata = kryo.readObject(input, classOf[RasterMetadata])
    val rasterFeature = kryo.readObject(input, classOf[RasterFeature])
    val fillValue = input.readInt()
    val pixelBitMaskLength = input.readInt()
    val pixelBitMask: Array[Byte] = if (pixelBitMaskLength > 0) input.readBytes(pixelBitMaskLength) else null
    val t = if (tiffTile.getNumSamples == 1) {
      if (tiffTile.getSampleFormat(0) == 1 || tiffTile.getSampleFormat(0) == 2)
        new GeoTiffTileInt(tileID, tiffTile, fillValue, pixelBitMask, metadata, rasterFeature)
      else if (tiffTile.getSampleFormat(0) == 3 && tiffTile.getBitsPerSample(0) == 32)
        new GeoTiffTileFloat(tileID, tiffTile, fillValue, pixelBitMask, metadata, rasterFeature)
      else if (tiffTile.getSampleFormat(0) == 3 && tiffTile.getBitsPerSample(0) == 64)
        new GeoTiffTileDouble(tileID, tiffTile, fillValue, pixelBitMask, metadata, rasterFeature)
    } else {
      // Array
      if (tiffTile.getSampleFormat(0) == 1 || tiffTile.getSampleFormat(0) == 2)
        new GeoTiffTileIntArray(tileID, tiffTile, fillValue, pixelBitMask, metadata, rasterFeature)
      else if (tiffTile.getSampleFormat(0) == 3 && tiffTile.getBitsPerSample(0) == 32)
        new GeoTiffTileFloatArray(tileID, tiffTile, fillValue, pixelBitMask, metadata, rasterFeature)
      else if (tiffTile.getSampleFormat(0) == 3 && tiffTile.getBitsPerSample(0) == 64)
        new GeoTiffTileDoubleArray(tileID, tiffTile, fillValue, pixelBitMask, metadata, rasterFeature)
    }
    t.asInstanceOf[AbstractGeoTiffTile[T]]
  }

def write(tile: ITile[T]): Unit = {
    numBands = tile.numComponents
    if (sampleFormats == null || bitsPerSample == null)
      inferSampleFormats(tile)
    val tileOffset: Long = tileDataOut.getPos

    // Since a tile is typically small, we first write the entire tile to memory and then compress if needed.
    val baos = new ByteArrayOutputStream()
    val dataOutput: OutputStream = compression match {
      case TiffConstants.COMPRESSION_NONE => baos
      case TiffConstants.COMPRESSION_LZW => new LZWOutputStream(baos)
      case TiffConstants.COMPRESSION_DEFLATE => new DeflaterOutputStream(baos)
    }
    val pixelOutput = new BitOutputStream(dataOutput)

    // According to TIFF specs, the data of all tiles must be equal to tileWidth x tileHeight
    // Even if it goes beyond the raster bounds
    val y2 = tile.y1 + rasterMetadata.tileHeight - 1
    val x2 = tile.x1 + rasterMetadata.tileWidth - 1
    for (j <- tile.y1 to y2; i <- tile.x1 to x2) {
      // TODO apply the difference predictor if needed
      if (j > tile.y2 || i > tile.x2 || tile.isEmpty(i, j)) {
        // Empty pixel. Write the fill value for all samples
        for (b <- 0 until numBands)
          pixelOutput.write(fillValue, bitsPerSample(b))
      } else {
        // A valid value
        if (numBands == 1) {
          tile.getPixelValue(i, j) match {
            case i: Byte => pixelOutput.write(i, bitsPerSample(0))
            case i: Short => pixelOutput.write(i, bitsPerSample(0))
            case i: Int => pixelOutput.write(i, bitsPerSample(0))
            case f: Float => pixelOutput.write(java.lang.Float.floatToIntBits(f), bitsPerSample(0))
            case d: Double => pixelOutput.write(java.lang.Double.doubleToLongBits(d), bitsPerSample(0))
          }
        } else {
          tile.getPixelValue(i, j) match {
            case is: Array[Int] =>
              for (b <- 0 until numBands)
                pixelOutput.write(is(b), bitsPerSample(b))
            case fs: Array[Float] =>
              for (b <- 0 until numBands)
                pixelOutput.write(java.lang.Float.floatToIntBits(fs(b)), bitsPerSample(b))
            case fs: Array[Double] =>
              for (b <- 0 until numBands)
                pixelOutput.write(java.lang.Double.doubleToLongBits(fs(b)), bitsPerSample(b))
            case os: Array[Any] =>
              for (b <- 0 until numBands) {
                os(b) match {
                  case i: Int => pixelOutput.write(i, bitsPerSample(b))
                  case f: Float => pixelOutput.write(java.lang.Float.floatToIntBits(f), bitsPerSample(b))
                  case d: Double => pixelOutput.write(java.lang.Double.doubleToLongBits(d), bitsPerSample(b))
                }
              }
          }
        }
      }
    }
    pixelOutput.close()
    val tileData = baos.toByteArray
    tileDataOut.write(tileData)
    val tileLength: Long = tileDataOut.getPos - tileOffset
    tileOffsetsLengthsOut.writeInt(tile.tileID)
    tileOffsetsLengthsOut.writeLong(tileOffset)
    tileOffsetsLengthsOut.writeLong(tileLength)
  }

def closeTileDataOnly(): Path = {
    tileDataOut.close()
    fileSystem.rename(tileDataPath, outPath)
    tileOffsetsLengthsOut.close()
    tileOffsetsLengthPath
  }

override def close(): Unit = {
    tileDataOut.close()
    tileOffsetsLengthsOut.close()
    // In addition to the bare data, we also need to prepend a header
    if (!bare)
      prependGeoTiffHeader(rasterMetadata, bitsPerSample, sampleFormats, compression, tileOffsetsLengthPath, fillValue,
        outPath, Array(tileDataPath), opts)
  }

def saveAsGeoTiff[T](rasterRDD: RDD[ITile[T]], outPath: String, opts: BeastOptions): Unit = {
    def maxArrayB(a: Array[Byte], b: Array[Byte]): Array[Byte] = {
      for (i <- a.indices)
        a(i) = a(i) max b(i)
      a
    }
    def maxArrayS(a: Array[Short], b: Array[Short]): Array[Short] = {
      for (i <- a.indices)
        a(i) = a(i) max b(i)
      a
    }
    def maxArrayI(a: Array[Int], b: Array[Int]): Array[Int] = {
      for (i <- a.indices)
        a(i) = a(i) max b(i)
      a
    }
    def maxArrayL(a: Array[Long], b: Array[Long]): Array[Long] = {
      for (i <- a.indices)
        a(i) = a(i) max b(i)
      a
    }
    if (!opts.contains(BitsPerSample) && opts.getBoolean(CompactBits, false)) {
      // Automatically compute bits per sample based on the maximum value
      val pixelType = rasterRDD.first().pixelType
      val measures = RasterOperationsGlobal.flatten(rasterRDD)
      val max: Array[Long] = pixelType match {
        case ByteType =>
          Array(measures.map(_._4.asInstanceOf[Byte]).reduce(_ max _))
        case ShortType =>
          Array(measures.map(_._4.asInstanceOf[Short]).reduce(_ max _))
        case IntegerType =>
          Array(measures.map(_._4.asInstanceOf[Int]).reduce(_ max _))
        case LongType =>
          Array(measures.map(_._4.asInstanceOf[Long]).reduce(_ max _))
        case ArrayType(ByteType, _) =>
          measures.map(_._4.asInstanceOf[Array[Byte]]).reduce(maxArrayB).map(_.toLong)
        case ArrayType(ShortType, _) =>
          measures.map(_._4.asInstanceOf[Array[Short]]).reduce(maxArrayS).map(_.toLong)
        case ArrayType(IntegerType, _) =>
          measures.map(_._4.asInstanceOf[Array[Int]]).reduce(maxArrayI).map(_.toLong)
        case ArrayType(LongType, _) =>
          measures.map(_._4.asInstanceOf[Array[Long]]).reduce(maxArrayL).map(_.toLong)
        case _ => null // Float types will not need a maximum value
      }
      if (max != null) {
        val bitsPerSample = max.map(x => MathUtil.log2(x + 1))
        opts.set(BitsPerSample, bitsPerSample.mkString(","))
        opts.set(FillValue, max.max + 1)
      }
    }
    opts.getString(WriteMode, "distributed") match {
      case "distributed" => saveAsGeoTiffDistributedMode(rasterRDD, outPath, opts)
      case "compatibility" => saveAsGeoTiffCompatibilityMode(rasterRDD, outPath, opts)
    }
  }

def prependGeoTiffHeader(rasterMetadata: RasterMetadata, bitsPerSample: Array[Int],
                           sampleFormats: Array[Int], compression: Int, tileOffsetsLengthsPath: Path,
                           fillValue: Int, outPath: Path, _tileDataPath: Array[Path],
                           opts: BeastOptions): Unit = {
    val numBands = bitsPerSample.length
    val software: String = "UCR Beast"
    var bigTiff: String = opts.getString(BigTiff, "auto")
    // 1. Prepare the list of entries
    var ifdEntries: mutable.ArrayBuffer[TempIFDEntry] = new ArrayBuffer[TempIFDEntry]()
    ifdEntries.append(makeIFDEntry(TiffConstants.TAG_SOFTWARE, TiffConstants.TYPE_ASCII, software))
    ifdEntries.append(makeIFDEntry(TiffConstants.TAG_IMAGE_WIDTH, TiffConstants.TYPE_LONG, rasterMetadata.rasterWidth))
    ifdEntries.append(makeIFDEntry(TiffConstants.TAG_IMAGE_LENGTH, TiffConstants.TYPE_LONG, rasterMetadata.rasterHeight))
    ifdEntries.append(makeIFDEntry(TiffConstants.TAG_SAMPLES_PER_PIXEL, TiffConstants.TYPE_SHORT, numBands))
    ifdEntries.append(makeIFDEntry(TiffConstants.TAG_BITS_PER_SAMPLE, TiffConstants.TYPE_SHORT, bitsPerSample))
    ifdEntries.append(makeIFDEntry(TiffConstants.TAG_SAMPLE_FORMAT, TiffConstants.TYPE_SHORT, Array.fill(numBands)(sampleFormats(0))))
    ifdEntries.append(makeIFDEntry(TiffConstants.TAG_COMPRESSION, TiffConstants.TYPE_SHORT, compression))
    ifdEntries.append(makeIFDEntry(TiffConstants.TAG_PHOTOMETRIC_INTERPRETATION, TiffConstants.TYPE_SHORT, 2))
    // Fill empty tiles with (0, 0) for offset and length. This no-GeoTiff-standard is supported by GDAL and Beast
    // See: https://gdal.org/drivers/raster/gtiff.html#sparse-files
    val tileOffsets: Array[Long] = new Array[Long](rasterMetadata.numTiles)
    val tileLengths: Array[Int] = new Array[Int](rasterMetadata.numTiles)
    val fileSystem: FileSystem = outPath.getFileSystem(opts.loadIntoHadoopConf())
    val tilesOffsetsLengthIn: FSDataInputStream = fileSystem.open(tileOffsetsLengthsPath)
    val tileMetadataLength: Long = fileSystem.getFileStatus(tileOffsetsLengthsPath).getLen
    while (tilesOffsetsLengthIn.getPos < tileMetadataLength) {
      val tileID: Int = tilesOffsetsLengthIn.readInt()
      tileOffsets(tileID) = tilesOffsetsLengthIn.readLong()
      tileLengths(tileID) = tilesOffsetsLengthIn.readLong().toInt
    }
    tilesOffsetsLengthIn.close()
    fileSystem.delete(tileOffsetsLengthsPath, false) // Clean up, no longer needed
    var tileDataPath = _tileDataPath
    if (tileLengths.contains(0) && opts.getBoolean(NoEmptyTiles, defaultValue = false)) {
      // Append an additional tile that is all empty to be pointed to by all non-existent tiles
      // This is to ensure compatibility with all readers that cannot detect tiles with zero length as empty
      val emptyTilePath = new Path(tileDataPath(0).getParent, "emptyTile.tif")
      val emptyTileOut = fileSystem.create(emptyTilePath)
      val dataOutput: OutputStream = compression match {
        case TiffConstants.COMPRESSION_NONE => emptyTileOut
        case TiffConstants.COMPRESSION_LZW => new LZWOutputStream(emptyTileOut)
        case TiffConstants.COMPRESSION_DEFLATE => new DeflaterOutputStream(emptyTileOut)
      }
      val pixelOutput = new BitOutputStream(dataOutput)
      for (_ <- 0 until rasterMetadata.tileWidth * rasterMetadata.tileHeight; b <- 0 until numBands)
        pixelOutput.write(fillValue, bitsPerSample(b))
      pixelOutput.close()
      val emptyTileLength: Int = fileSystem.getFileStatus(emptyTilePath).getLen.toInt
      // We always append the empty tile so the offset is after the last tile
      var emptyTileOffset: Long = 0
      for (iTile <- tileOffsets.indices)
        emptyTileOffset = emptyTileOffset max (tileOffsets(iTile) + tileLengths(iTile))
      // Now, append the empty tile path to the list of paths and set its offset and length for all empty tiles
      for (iTile <- tileOffsets.indices; if tileLengths(iTile) == 0) {
        tileOffsets(iTile) = emptyTileOffset
        tileLengths(iTile) = emptyTileLength
      }
      tileDataPath = tileDataPath :+ emptyTilePath
    }
    // If the file has only one strip or tile, the offset and length should be encoded in the IFD Entry
    if (rasterMetadata.tileWidth == rasterMetadata.rasterWidth) {
      // Stripped file
      ifdEntries.append(makeIFDEntry(TiffConstants.TAG_STRIP_OFFSETS, TiffConstants.TYPE_LONG, tileOffsets))
      ifdEntries.append(makeIFDEntry(TiffConstants.TAG_STRIP_BYTE_COUNTS, TiffConstants.TYPE_LONG, tileLengths))
      ifdEntries.append(makeIFDEntry(TiffConstants.TAG_ROWS_PER_STRIP, TiffConstants.TYPE_LONG, rasterMetadata.tileHeight))
    } else {
      // Tiled file
      ifdEntries.append(makeIFDEntry(TiffConstants.TAG_TILE_OFFSETS, TiffConstants.TYPE_LONG, tileOffsets))
      ifdEntries.append(makeIFDEntry(TiffConstants.TAG_TILE_BYTE_COUNTS, TiffConstants.TYPE_LONG, tileLengths))
      ifdEntries.append(makeIFDEntry(TiffConstants.TAG_TILE_WIDTH, TiffConstants.TYPE_LONG, rasterMetadata.tileWidth))
      ifdEntries.append(makeIFDEntry(TiffConstants.TAG_TILE_LENGTH, TiffConstants.TYPE_LONG, rasterMetadata.tileHeight))
    }
    ifdEntries.append(makeIFDEntry(TiffConstants.TAG_PLANAR_CONFIGURATION, TiffConstants.TYPE_SHORT, 1))
    // Fill value
    ifdEntries.append(makeIFDEntry(GeoTiffConstants.GDALNoDataTag, TiffConstants.TYPE_ASCII, fillValue.toString))
    if (rasterMetadata.srid != 0) {
      val crs: CoordinateReferenceSystem = CRSServer.sridToCRS(rasterMetadata.srid)
      val adapter = new CRS2GeoTiffMetadataAdapter(crs)
      val data = adapter.parseCoordinateReferenceSystem()
      val entryData = new Array[Int](data.getNumGeoKeyEntries * 4)
      var doubleParams: Array[Double] = Array()
      var asciiParams: String = ""
      entryData(0) = data.getGeoTIFFVersion
      entryData(1) = data.getKeyRevisionMajor
      entryData(2) = data.getKeyRevisionMinor
      entryData(3) = data.getNumGeoKeyEntries - 1
      for (i <- 1 until data.getNumGeoKeyEntries) {
        val geoKeyEntry = data.getGeoKeyEntryAt(i)
        entryData(i * 4 + 0) = geoKeyEntry.getKeyID
        entryData(i * 4 + 1) = geoKeyEntry.getTiffTagLocation
        entryData(i * 4 + 2) = geoKeyEntry.getCount
        entryData(i * 4 + 3) = geoKeyEntry.getValueOffset
        if (geoKeyEntry.getTiffTagLocation.toShort == GeoTiffConstants.GeoDoubleParamsTag) {
          entryData(i * 4 + 3) = doubleParams.length
          doubleParams = doubleParams ++ data.getGeoDoubleParams(geoKeyEntry.getKeyID)
        }
        if (geoKeyEntry.getTiffTagLocation.toShort == GeoTiffConstants.GeoAsciiParamsTag) {
          entryData(i * 4 + 3) = asciiParams.length
          asciiParams = asciiParams + data.getGeoAsciiParam(geoKeyEntry.getKeyID)
        }
      }
      ifdEntries.append(makeIFDEntry(GeoTiffConstants.GeoKeyDirectoryTag, TiffConstants.TYPE_SHORT, entryData))
      if (doubleParams.nonEmpty)
        ifdEntries.append(makeIFDEntry(GeoTiffConstants.GeoDoubleParamsTag, TiffConstants.TYPE_DOUBLE, doubleParams))
      if (asciiParams.nonEmpty)
        ifdEntries.append(makeIFDEntry(GeoTiffConstants.GeoAsciiParamsTag, TiffConstants.TYPE_ASCII, asciiParams))
    }
    // Write Affine Transform
    if (rasterMetadata.g2m != null) {
      val affineTransform = rasterMetadata.g2m
      if (affineTransform.getShearX == 0.0 & affineTransform.getShearY == 0.0) {
        // The most common special case when no shearing is in the transformation matrix
        ifdEntries.append(makeIFDEntry(GeoTiffConstants.ModelTiepointTag, TiffConstants.TYPE_DOUBLE,
          Array(0.0, 0.0, 0.0, affineTransform.getTranslateX, affineTransform.getTranslateY, 0.0)))
        ifdEntries.append(makeIFDEntry(GeoTiffConstants.ModelPixelScaleTag, TiffConstants.TYPE_DOUBLE,
          Array(affineTransform.getScaleX, -affineTransform.getScaleY, 0.0)))
      } else {
        // TODO A full affine transformation, write all entries
        throw new RuntimeException("Full affine transformations not yet supported")
      }
    }
    // Sort by tag as required by TIFF specifications
    ifdEntries = ifdEntries.sortBy(_.tag & 0xffff)
    // The array of tile lengths in bytes. Used to calculate overall data size
    val lengthsArray: Array[Int] = ifdEntries
      .find(e => e.tag == TiffConstants.TAG_TILE_BYTE_COUNTS || e.tag == TiffConstants.TAG_STRIP_BYTE_COUNTS)
      .get.value.asInstanceOf[Array[Int]]

    // 2. Now, calculate the size of the header to assign offsets to IFD entries and adjust tile offsets in file
    val dataSize: Long = lengthsArray.map(_.toLong).sum
    var metadataSize: Long = if (bigTiff == "yes") calculateHeaderSizeBigTiff(ifdEntries) else calculateHeaderSizeNormalTiff(ifdEntries)
    val totalSize = metadataSize + dataSize
    if (totalSize > Int.MaxValue) {
      if (bigTiff == "no")
        throw new RuntimeException(s"Tiff file size $totalSize exceeds the maximum of ${Int.MaxValue} and BigTiff flag is set to '${bigTiff}'")
      // Set the big tiff flag and recalculate the header size
      if (bigTiff == "auto") {
        bigTiff = "yes"
        logInfo(s"Automatically switched to BigGeoTiff to handle an estimated file of size $totalSize")
      }
      // Update the type of the tile offset to 8 bytes
      for (i <- ifdEntries.indices) {
        if (ifdEntries(i).tag == TiffConstants.TAG_TILE_OFFSETS || ifdEntries(i).tag == TiffConstants.TAG_STRIP_OFFSETS)
          ifdEntries(i) = makeIFDEntry(ifdEntries(i).tag, TiffConstants.TYPE_LONG8, ifdEntries(i).value)
      }
      // Recalculate metadata size for Big TIFF
      metadataSize = calculateHeaderSizeBigTiff(ifdEntries)
    } else {
      // The file size is small. No need for Big TIFF
      if (bigTiff == "yes")
        logInfo("Unnecessarily writing a Big GeoTiff file")
      else if (bigTiff == "auto")
        bigTiff = "no"
    }
    // Update tile offsets based on the metadata size since tiles will be written after the header + metadata
    val offsetsArray: Array[Long] = ifdEntries
      .find(e => e.tag == TiffConstants.TAG_TILE_OFFSETS || e.tag == TiffConstants.TAG_STRIP_OFFSETS)
      .get.value.asInstanceOf[Array[Long]]
    // Update offsets only for tile with positive length. Tiles with zero length are invalid and should have offset=0
    // See: https://gdal.org/drivers/raster/gtiff.html#sparse-files
    for (tileID <- offsetsArray.indices; if lengthsArray(tileID) > 0)
      offsetsArray(tileID) = offsetsArray(tileID) + metadataSize

    val headerPath = new Path(outPath.toString + "_header")
    // 3. Write the actual file to the given output stream
    val headerOut = fileSystem.create(headerPath)
    if (bigTiff == "no")
      writeNormalHeader(headerOut, ifdEntries)
    else
      writeBigHeader(headerOut, ifdEntries)
    headerOut.close()

    // Concatenate both files
    FileUtil.concat(fileSystem, outPath, (headerPath +: tileDataPath):_*)
  }

def count: Int = value match {
      case ar: Array[Int] => ar.length
      case ar: Array[Long] => ar.length
      case ar: Array[Double] => ar.length
      case str: String => str.length + 1
    }

def getValueOrOffsetNormal(bigEndian: Boolean = true): Int = {
      if (valueLength > 4) {
        offset.toInt
      } else value match {
        case ar: Array[Int] => IFDEntry.makeValue(valueType, ar, bigEndian)
        case ar: Array[Long] => IFDEntry.makeValue(valueType, ar.map(_.toInt), bigEndian)
        case str: String => IFDEntry.makeValue(valueType, (str.getBytes.map(_.toInt) :+ 0), bigEndian)
      }
    }

def getValueOrOffsetBig(bigEndian: Boolean = true): Long = {
      if (valueLength > 8) {
        offset
      } else value match {
        case ar: Array[Int] => BigIFDEntry.makeValueBig(valueType, ar.map(_.toLong), bigEndian)
        case ar: Array[Long] => BigIFDEntry.makeValueBig(valueType, ar, bigEndian)
        case str: String => BigIFDEntry.makeValueBig(valueType, str.getBytes.map(_.toLong) :+ 0L, bigEndian)
      }
    }

override def toString: String = {
      val valueString: String = value match {
        case s: String => s"'${s}'"
        case v: Array[Int] => s"[${v.mkString(",")}]"
        case ar: Array[Double] => s"[${ar.mkString(",")}]"
        case ar: Array[Long] => s"[${ar.mkString(",")}]"
      }
      val tagName: String = TiffConstants.TagNames.get(tag)
      s"IFDEntry #${tag} ${tagName} value ${valueString} offset ${offset}"
    }

override def initialize(fileSystem: FileSystem, path: String, layer: String, opts: BeastOptions): Unit = {
    super.initialize(fileSystem, path, layer, opts)
    if (this.hdfFile != null) {
      // In case the reader is reused without properly closing it
      this.close()
    }

    rasterFeature = RasterFeature.create(Array("fileName"), Array(path))

    this.hdfFile = new HDFFile(path.toString)
    // Retrieve the h and v values (only for MODIS files from the LP DAAC archive)
    val archiveMetadata = hdfFile.findHeaderByName("ArchiveMetadata.0").getEntryAt(0).asInstanceOf[String]
    val coreMetadata = hdfFile.findHeaderByName("CoreMetadata.0").getEntryAt(0).asInstanceOf[String]
    try {
      this.h = getIntByName(archiveMetadata, "HORIZONTALTILENUMBER")
      this.v = getIntByName(archiveMetadata, "VERTICALTILENUMBER")
    } catch {
      case e: RuntimeException =>
        // For WaterMask (MOD44W), these values are found somewhere else
        try {
          this.h = getIntByName(coreMetadata, "HORIZONTALTILENUMBER")
          this.v = getIntByName(coreMetadata, "VERTICALTILENUMBER")
        } catch {
          case e2: RuntimeException =>
            throw new RuntimeException("Could not getPixel h and v values for an HDF file")
        }
    }
    // DATACOLUMNS is not available in MODIS temperature product MOD11A1.006
    //this.resolution = getIntByName(archiveMetadata, "DATACOLUMNS");
    this.loadRasterMetadata()
    val srid = CRSServer.crsToSRID(SinusoidalCRS)
    // Create an affine transformation for a model space in the sinusoidal projection
    val affineMatrix = Array(TileWidth / resolution, 0, 0, -1 * TileHeight / resolution, MinX + h * TileWidth, MaxY - v * TileHeight)
    val g2m: AffineTransform = new AffineTransform(affineMatrix)
    this._metadata = new RasterMetadata(0, 0, resolution, resolution, resolution, resolution, srid, g2m)
  }

def loadRasterMetadata(): Unit = {
    // Find the required dataset and read it
    val dataGroup = hdfFile.findGroupByName(getLayerName)
    require(dataGroup != null, s"Could not find the layer '${getLayerName}' in the HDF file")
    this.scaleFactor = 1.0f
    for (dd <- dataGroup.getContents; if dd.isInstanceOf[DDVDataHeader]) {
          val vheader = dd.asInstanceOf[DDVDataHeader]
      vheader.getName match {
        case "_FillValue" => {
          this.fillValue = vheader.getEntryAt(0) match {
            case i: Integer => i
            case s: java.lang.Short => s.toInt
            case b: java.lang.Byte => b.toInt
          }
          fillValueValid = true
        }
        case "valid_range" => {
          this.minValue = vheader.getEntryAt(0) match {
            case i: Integer => i
            case s: java.lang.Short => s.toInt
            case b: java.lang.Byte => b.toInt
          }
          this.maxValue = vheader.getEntryAt(1) match {
            case i: Integer => i
            case s: java.lang.Short => s.toInt
            case b: java.lang.Byte => b.toInt
          }
        }
        case "scale_factor" => {
          this.scaleFactor =  vheader.getEntryAt(0) match {
            case i: Integer => i.toDouble
            case b: java.lang.Byte => b.toDouble
            case f: java.lang.Float => f.toDouble
            case d: java.lang.Double => d
          }
          // Hack: The scale factor in NDVI data is listed as 10,000 but it should be 1/10,000
          // See: https://lpdaac.usgs.gov/products/mod13q1v006/
          if (scaleFactor == 10000.0) scaleFactor = 1 / 10000.0
        }
        case _ => // Ignore
      }
    }
    // Retrieve data size
    for (dd <- dataGroup.getContents; if dd.isInstanceOf[DDNumericDataGroup]) {
      val numericDataGroup = dd.asInstanceOf[DDNumericDataGroup]
      // A bug causes the numericDataGroup to be not loaded. toString will force loading it
      numericDataGroup.toString
      this.resolution = numericDataGroup.getDimensions()(0)
    }
  }

override def readTile(tileID: Int): ITile[Float] = {
    require(tileID == 0, "Invalid tile number")
    val dataGroup = hdfFile.findGroupByName(getLayerName)
    require(dataGroup != null, s"Could not find the layer '${getLayerName}' in the HDF file")

    // Retrieve data size
    for (dd <- dataGroup.getContents; if dd.isInstanceOf[DDNumericDataGroup]) {
      val numericDataGroup = dd.asInstanceOf[DDNumericDataGroup]
      val valueSize: Int = numericDataGroup.getDataSize
      val unparsedDataArray: Array[Byte] = new Array[Byte](valueSize * resolution * resolution)
      if (fillValueValid) {
        val fillValueBytes = new Array[Byte](valueSize)
        HDFConstants.writeAt(fillValueBytes, 0, this.fillValue, valueSize)
        for (i <- unparsedDataArray.indices)
          unparsedDataArray(i) = fillValueBytes(i % valueSize)
      }
      numericDataGroup.getAsByteArray(unparsedDataArray, 0, unparsedDataArray.length)
      val dataBuffer = ByteBuffer.wrap(unparsedDataArray)
      return new HDFTile(tileID, dataBuffer.array(), valueSize, fillValue, scaleFactor, metadata, rasterFeature)
    }
    // Tile not found
    null
  }

def createTileIDFilter(rect: Rectangle2D): PathFilter = {
    val hMin = ((rect.getX - MinX) / TileWidth).toInt
    val hMax = ((rect.getMaxX - MinX) / TileWidth).toInt
    val vMax = ((-rect.getY - MinY) / TileHeight).toInt
    val vMin = ((-rect.getMaxY - MinY) / TileHeight).toInt
    val tileRange = new Rectangle(hMin, vMin, hMax - hMin + 1, vMax - vMin + 1)
    p: Path => {
      val matcher = ModisTileIDRegex.matcher(p.getName)
      if (!matcher.matches)
        false
      else {
        val h = matcher.group(1).toInt
        val v = matcher.group(2).toInt
        tileRange.contains(h, v)
      }
    }
  }

def createDateFilter(dateStart: String, dateEnd: String): PathFilter = {
    val startTime = DateFormat.parse(dateStart).getTime
    val endTime = DateFormat.parse(dateEnd).getTime
    (p: Path) => { try {
        val time = DateFormat.parse(p.getName).getTime
        time >= startTime && time <= endTime
      } catch {
        case e: ParseException => false
      }
    }
  }

override def getPixelValue(i: Int, j: Int): Float = {
    val intVal = valueSize match {
      case 1 => data((j * resolution + i) * valueSize) & 0xff
      case 2 => getShort((j * resolution + i) * valueSize)
      case 4 => getInt((j * resolution + i) * valueSize)
    }
    (intVal * scaleFactor).toFloat
  }

override def isEmpty(i: Int, j: Int): Boolean = {
    valueSize match {
      case 1 =>
        data((j * resolution + i) * valueSize) == fillValue
      case 2 =>
        getShort((j * resolution + i) * valueSize) == fillValue
      case 4 =>
        getInt((j * resolution + i) * valueSize) == fillValue
    }
  }

override def getShort(i: Int): Short = {
    (((data(i) & 0xff) << 8) | ((data(i+1) & 0xff))).toShort
  }

override def getInt(i: Int): Int = {
    (data(i + 3) & 0xff |
      (data(i + 2) & 0xff << 8) |
      (data(i + 1) & 0xff << 16) |
      (data(i) & 0xff << 24)).toShort
  }

