def next: (Long, PixelRange) = {
    if (currentI == -1 || currentRange == currentIntersection.getNumIntersections - 1) {
      // First time or finished the current intersection
      currentI += 1
      assert(currentIntersection.getNumIntersections > 0)
      currentRange = 0
    } else {
      currentRange += 1
    }
    fileTileID = (FileIDs(currentI).toLong << 32) | currentIntersection.getTileID(currentRange)
    geometryID = currentIntersection.getFeatureID(currentRange)
    y = currentIntersection.getY(currentRange)
    x1 = currentIntersection.getX1(currentRange)
    (fileTileID, PixelRange(geometryID, y, x1, currentIntersection.getX2(currentRange)))
  }

implicit def orderingByPolygonID[A <: IntersectionsIterator ] : Ordering[A] = {
    Ordering.by(x => (x.fileTileID,x.geometryID,x.y,x.x1))
  }

override def next(): (Long, PixelRange) = {
    if(j == -1)
    {
      intersections = intersectionsList.get(i)
      sizeI = intersections.getNumIntersections
      j=0
      FileID = FileIDs.get(i)
    }

    TileID = intersections.getTileID(j)
    PolygonIndex = intersections.getPolygonIndex(j)
    Y = intersections.getY(j)
    X1 = intersections.getX1(j)
    X2 = intersections.getX2(j)
    j=j+1
    RasterSplitID = ((FileID.toLong << 32) + TileID)

    if(j==sizeI)
    {
      i = i + 1
      j = -1
    }

    // System.out.println(PolygonIndex)
    (RasterSplitID, PixelRange(PolygonIndex,Y,X1,X2))
  }

implicit def orderingByPolygonID[A <: IntersectionsIterator1 ] : Ordering[A] = {
    Ordering.by(x => (x.RasterSplitID,x.PolygonIndex,x.Y,x.X1))
  }

override def write(kryo: Kryo, output: Output, tile: MaskTile[T]): Unit = {
    kryo.writeClassAndObject(output, tile.tile)
    output.writeLongs(tile.mask)
  }

override def read(kryo: Kryo, input: Input, tileClass: Class[MaskTile[T]]): MaskTile[T] = {
    val tile: ITile[T] = kryo.readClassAndObject(input).asInstanceOf[ITile[T]]
    val mask = input.readLongs((tile.tileWidth * tile.tileHeight + 63) / 64)
    new MaskTile[T](tile, mask)
  }

override def getPixelValue(i: Int, j: Int): T = {
    var pixelOffset = getPixelOffset(i, j) * bitsPerPixel
    if (numComponents == 1) {
      // A single value
      parseComponentValue(pixelOffset).asInstanceOf[T]
    } else {
      val pixelValue: Array[_] = tempPixelValue.clone()
      for (i <- 0 until numComponents) {
        val rawValue: Any = parseComponentValue(pixelOffset)
        java.lang.reflect.Array.set(pixelValue, i, rawValue)
        pixelOffset += bitsPerComponent
      }
      pixelValue.asInstanceOf[T]
    }
  }

def setPixelValue(i: Int, j:Int, value: T): Unit = {
    if (compression != 0)
      decompress
    var pixelOffset = getPixelOffset(i, j)
    BitArray.setBit(pixelExists, pixelOffset)
    if (numComponents == 1) {
      // A single value
      pixelOffset *= bitsPerPixel
      setComponentValue(pixelOffset, value)
    } else {
      if (numComponents == 0) {
        // First value to set, initialize number of components from it
        numComponents = java.lang.reflect.Array.getLength(value)
        data = new Array[Long](((this.tileWidth * this.tileHeight) * bitsPerPixel + 63) / 64)
      }
      pixelOffset *= bitsPerPixel
      assert(java.lang.reflect.Array.getLength(value) == numComponents, s"Mismatching value length" +
        s" ${java.lang.reflect.Array.getLength(value)} and number of components ${numComponents}")
      value match {
        case xs: Array[_] => for (x <- xs) {
          setComponentValue(pixelOffset, x)
          pixelOffset += bitsPerComponent
        }
        case _ => throw new RuntimeException(s"Unrecognized value type ${value.getClass}")
      }
    }
  }

def setPixelValue(i: Int, j: Int, value: T): Unit = {
    if (_numComponents == 0) {
      // First value to set, initialize number of components from it
      _numComponents = java.lang.reflect.Array.getLength(value)
    }
    val offset = pixelOffset(i, j)
    pixelDefined.set(offset, true)
    pixelValue(offset) = value
  }

override def read(kryo: Kryo, input: Input, klass: Class[MemoryTile[Any]]): MemoryTile[Any] = {
    // Read a tile and do not decompress immediately. Let it lazily decompress when needed
    val tileID: Int = input.readInt()
    val metadata = kryo.readObject(input, classOf[RasterMetadata])
    val rasterFeature = kryo.readObject(input, classOf[RasterFeature])
    // Note: We use [Byte] to make the code compile and run but we override the info in the next lines
    val tile = new MemoryTile[Byte](tileID, metadata, rasterFeature)
    tile.componentTypeNumber = input.readInt()
    tile.bitsPerComponent = MemoryTile.NumberOfBitsPerType(tile.componentTypeNumber)
    tile.numComponents = input.readInt()
    for (i <- tile.pixelExists.indices)
      tile.pixelExists(i) = input.readLong()
    tile.compression = input.readInt()
    tile.data = input.readLongs(input.readInt())
    tile.asInstanceOf[MemoryTile[Any]]
  }

def create[T: ClassTag](tileID: Int, metadata: RasterMetadata, rasterFeature: RasterFeature, numValues: Int): MemoryTileWindow[T] = {
    val w = new MemoryTileWindow[T](tileID, metadata, rasterFeature, numValues, new Array[MemoryTile[T]](numValues))
    for (i <- 0 until numValues)
      w.tiles(i) = new MemoryTile[T](tileID, metadata, rasterFeature)
    w
  }

override def write(kryo: Kryo, output: Output, tile: MemoryTileWindow[T]): Unit = {
    output.writeInt(tile.numValues)
    for (i <- 0 until tile.numValues)
      kryo.writeObject(output, tile.tiles(i))
  }

override def read(kryo: Kryo, input: Input, klass: Class[MemoryTileWindow[T]]): MemoryTileWindow[T] = {
    val numValues = input.readInt()
    val tiles = new Array[MemoryTile[T]](numValues)
    for (i <- 0 until numValues)
      tiles(i) = kryo.readObject(input, classOf[MemoryTile[T]])
    MemoryTileWindow.create(tiles)
  }

override def next: RaptorJoinResult[T] = {
    val toReturn = nextTuple
    nextTuple = prefetchNext
    toReturn
  }

override def next: RaptorJoinResult[T] = {
    val toReturn = nextTuple
    nextTuple = prefetchNext
    toReturn
  }

override def compareTo(o: Intersection): Int = {
      var diff: Int = this.j - o.j
      if (diff == 0)
        diff = this.pID - o.pID
      if (diff == 0)
        diff = this.i - o.i
      diff
    }

override def compareTo(o: IntersectionRange): Int = {
      var diff: Int = this.j - o.j
      if (diff == 0)
        diff = this.pID - o.pID
      if (diff == 0)
        diff = this.i1 - o.i1
      if (diff == 0)
        diff = this.i2 - o.i2
      diff
    }

override def next(): (Int, Int, Int) = {
    val pid: Int = intersectionPId.next().toInt
    val i: Int = intersectionX.next().toInt
    val j: Int = intersectionY.next().toInt
    (pid, i, j)
  }

