override def compute(split: Partition, context: TaskContext): Iterator[ITile[T]] = {
    logDebug(s"Processing $split")
    val rasterPartition: RasterFilePartition = split.asInstanceOf[RasterFilePartition]
    val rasterPath = new Path(rasterPartition.path)
    val fileSystem = rasterPath.getFileSystem(opts.loadIntoHadoopConf())
    val rasterReader: IRasterReader[T] = RasterHelper.createRasterReader(fileSystem, rasterPath, opts)
    context.addTaskCompletionListener[Unit] { context =>
      // TODO: Update the bytes read before closing is to make sure lingering bytesRead statistics in
      // this thread get correctly added.
      // Close the reader of free up resources
      rasterReader.close()
    }

    // Sort by tileOffset, avoid random seek position
    val tileIds = rasterReader.getTileOffsets.zipWithIndex.filter(idpos => {
      rasterReader.isValidTile(idpos._2) &&
        idpos._1 >= rasterPartition.offset && idpos._1 < rasterPartition.offset + rasterPartition.length
    }).sortBy(x => x._1).map(_._2)
    tileIds.iterator.map(tid => rasterReader.readTile(tid))
  }

def buildIndex(sparkContext: SparkContext, dir: String, indexFile: String): Unit = {
    val hadoopConf = sparkContext.hadoopConfiguration
    val opts = new BeastOptions(hadoopConf)
    val files: RDD[String] = FileListRDD.listFiles(sparkContext, dir, "*.tif")
    val indexInfo = files.map(filename => {
      val rasterPath = new Path(dir, filename)
      val infs = rasterPath.getFileSystem(opts.loadIntoHadoopConf(null))
      val filesize = infs.getFileStatus(rasterPath).getLen
      val metadata = GeoTiffReader.getRasterMetadata(infs, rasterPath)
      val mbr: Envelope = metadata.envelope
      val srid: Int = metadata.srid
      val mbrCorners: Array[Float] = Array[Double](mbr.getMinX, mbr.getMinY, mbr.getMaxX, mbr.getMinY,
        mbr.getMaxX, mbr.getMaxY, mbr.getMinX, mbr.getMaxY, mbr.getMinX, mbr.getMinY).map(_.toFloat)
      val t = Reprojector.findTransformationInfo(srid, 4326)
      t.mathTransform.transform(mbrCorners, 0, mbrCorners, 0, 4)
      // Close the ring
      mbrCorners(8) = mbrCorners(0)
      mbrCorners(9) = mbrCorners(1)
      (new Path(filename).getName, filesize, mbr, srid, mbrCorners)
    }).collect().sortBy(_._1).zipWithIndex
    // Write index information to a CSV file
    val indexPath: Path = new Path(indexFile)
    val indexFS = indexPath.getFileSystem(hadoopConf)
    val out = new PrintStream(indexFS.create(indexPath))
    try {
      out.println(Seq("ID","FileName","FileSize","x1","y1","x2","y2","SRID","Geometry4326").mkString(";"))
      val geomFactory = new GeometryFactory()
      indexInfo.foreach(f => {
        val geometry = geomFactory.createPolygon(f._1._5.grouped(2).map(c => new Coordinate(c(0), c(1))).toArray)
        out.println(Seq(f._2, f._1._1, f._1._2,
          f._1._3.getMinX, f._1._3.getMinY, f._1._3.getMaxX, f._1._3.getMaxY,
          f._1._4, geometry.toText).mkString(";"))
      })
    } finally {
      out.close()
    }
  }

def selectFiles(fileSystem: FileSystem, dir: String, range: Geometry): Array[String] = {
    if (fileSystem.getFileStatus(new Path(dir)).isFile) {
      // The input points to a single file, just return it
      return Array(dir)
    }
    val indexFile = new Path(dir, "_index.csv")
    if (!fileSystem.exists(indexFile)) {
      // No index file, return all directory contents
      return getRasterFiles(fileSystem, new Path(dir)).map(_.getPath.toString)
    }
    // Use the index file to return only matching files
    val matchingFiles = new ArrayBuffer[String]()
    val inputStream = fileSystem.open(indexFile)
    try {
      val lines: Iterator[String] = Source.fromInputStream(inputStream).getLines()
      val header: Array[String] = lines.next.split(";")
      val mbrAtts = header.indexOf("x1")
      val filenameAttr = header.indexOf("FileName")
      val sridAttr = header.indexOf("SRID")
      for (line <- lines) {
        val data: Array[String] = line.split(";").map(_.trim)
        val mbr = data.slice(mbrAtts, mbrAtts + 4).map(_.toDouble)
        val srid = data(sridAttr).toInt
        if (srid != range.getSRID && srid != 0 && range.getSRID != 0)
          Reprojector.reprojectEnvelopeInPlace(mbr, srid, range.getSRID)
        if (range.intersects(range.getFactory.toGeometry(new Envelope(mbr(0), mbr(2), mbr(1), mbr(3))))) {
          matchingFiles.append(new Path(dir, data(filenameAttr)).toString)
        }
      }
    } finally {
      inputStream.close()
    }
    matchingFiles.toArray
  }

def reshapeAverage[T: ClassTag](raster: RasterRDD[T], targetMetadataConv: RasterMetadata => RasterMetadata,
                                  _numPartitions: Int = 0): RasterRDD[T] = {
    val intermediateTiles: RDD[(Int, MemoryTile[Array[Float]])] = raster.flatMap(sourceTile => {
      val targetMetadata: RasterMetadata = targetMetadataConv(sourceTile.rasterMetadata)
      val numIntermediateValues = sourceTile.numComponents + 1
      val accumulator: (Array[Float], T) => Unit = accumulators(sourceTile.pixelType).asInstanceOf[(Array[Float], T) => Unit]

      // We need a transformer that transforms a pixel in source to the target pixel in target and vice-versa
      // These are the steps needed to transform from source to target:
      // 1- Use source metadata grid-to-model to convert from source raster space to source model space
      // 2- Use CRS transformation to transform from source model space to target model space
      // 3- Use target metadata model-to-grid to convert from target model space to target grid space
      // To do all these steps efficiently, we concatenate all these transformations into one
      val sourceG2M = new AffineTransform2D(sourceTile.rasterMetadata.g2m)
      val transformationInfo = Reprojector.findTransformationInfo(sourceTile.rasterMetadata.srid, targetMetadata.srid)
      val targetM2G = new AffineTransform2D(targetMetadata.g2m).inverse()
      val sourceToTarget = concatenateTransforms(sourceG2M, transformationInfo.mathTransform, targetM2G)
      val targetToSource = sourceToTarget.inverse()

      // First, convert the bounding box of the entire source tile to know the range of target tiles
      val tileCorners = Array[Double](sourceTile.x1, sourceTile.y1,
        sourceTile.x2 + 1, sourceTile.y1,
        sourceTile.x2 + 1, sourceTile.y2 + 1,
        sourceTile.x1, sourceTile.y2 + 1,
      )
      sourceToTarget.transform(tileCorners, 0, tileCorners, 0, 4)
      // Convert to a range of pixels in the target. This range is *exclusive*
      // The target range contains all pixels that partially overlap this pixel
      val targetRasterX1: Int = ((tileCorners(0) min tileCorners(2) min tileCorners(4) min tileCorners(6)) max targetMetadata.x1).toInt
      val targetRasterX2: Int = (((tileCorners(0) max tileCorners(2) max tileCorners(4) max tileCorners(6))+1.0) min targetMetadata.x2).toInt
      val targetRasterY1: Int = ((tileCorners(1) min tileCorners(3) min tileCorners(5) min tileCorners(7)) max targetMetadata.y1).toInt
      val targetRasterY2: Int = (((tileCorners(1) max tileCorners(3) max tileCorners(5) max tileCorners(7))+1.0) min targetMetadata.y2).toInt


      // The most general (and heavy) method for creating intermediate tiles
      val createIntermediateTilesGeneral: Int => (Int, MemoryTile[Array[Float]]) = targetTileID => {
        var emptyTile = true
        val targetTile = new MemoryTile[Array[Float]](targetTileID, targetMetadata, sourceTile.rasterFeature)
        // (x1,y1)-(x2,y2) is an inclusive range of target pixels that match with this tile
        val targetTileX1 = targetTile.x1 max targetRasterX1
        val targetTileX2 = targetTile.x2 min targetRasterX2
        val targetTileY1 = targetTile.y1 max targetRasterY1
        val targetTileY2 = targetTile.y2 min targetRasterY2
        for (targetY <- targetTileY1 to targetTileY2; targetX <- targetTileX1 to targetTileX2) {
          // Convert this pixel to a box in the source dataset
          val pixelCorners = Array[Double](targetX, targetY, targetX + 1, targetY + 1)
          targetToSource.transform(pixelCorners, 0, pixelCorners, 0, 2)
          // Now, the range is still inclusive of the first pixel and exclusive of the last pixel
          // If the first and last pixels are the same, we still read the first pixel
          // Now, we can now loop over all source pixels and aggregate them.
          val sourceX1: Int = pixelCorners(0).toInt max sourceTile.x1
          // The -0.5 in the following equations is to ensure that we include up-to the last pixel that has
          // its center in the converted pixel coordinates.
          val sourceX2: Int = (pixelCorners(2) - 0.5).toInt min sourceTile.x2
          val sourceY1: Int = pixelCorners(1).toInt max sourceTile.y1
          val sourceY2: Int = (pixelCorners(3) - 0.5).toInt min sourceTile.y2
          var sourceX = sourceX1
          var sourceY = sourceY1
          val accumulate = new Array[Float](numIntermediateValues)
          while (sourceX <= sourceX2 && sourceY <= sourceY2) {
            if (sourceTile.isDefined(sourceX, sourceY))
              accumulator(accumulate, sourceTile.getPixelValue(sourceX, sourceY))
            sourceX += 1
            if (sourceX > sourceX2) {
              sourceX = sourceX1
              sourceY += 1
            }
          }
          if (accumulate.last > 0) {
            // Found at least one pixel
            targetTile.setPixelValue(targetX, targetY, accumulate)
            emptyTile = false
          }
        }
        if (emptyTile)
          (targetTileID, null)
        else
          (targetTileID, targetTile)
      }

      // Create intermediate tiles when the transformation is simple and a source pixel is bigger than a target one
      // In this case, each target pixel has at most one value
      val createIntermediateTilesSimpleSourcePixelBigger: Int => (Int, MemoryTile[Array[Float]]) = targetTileID => {
        var emptyTile = true
        val targetTile = new MemoryTile[Array[Float]](targetTileID, targetMetadata, sourceTile.rasterFeature)
        // An inclusive range of all target pixels that will be calculated for this tile
        val allTargetPixelRange = Array[Double](
          targetTile.x1 max targetRasterX1, targetTile.y1 max targetRasterY1,
          targetTile.x2 min targetRasterX2, targetTile.y2 min targetRasterY2
        )
        var targetPixelX1: Int = allTargetPixelRange(0).toInt
        var targetPixelY1: Int = allTargetPixelRange(1).toInt
        // The source pixel being read
        val sourcePixelRange = new Array[Double](4)
        targetToSource.transform(allTargetPixelRange, 0, sourcePixelRange, 0, 2)
        sourcePixelRange(2) = sourcePixelRange(2) min sourceTile.x2
        sourcePixelRange(3) = sourcePixelRange(3) min sourceTile.y2
        var sourceX = sourcePixelRange(0).toInt
        var sourceY = sourcePixelRange(1).toInt
        while (sourceX <= sourcePixelRange(2) && sourceY <= sourcePixelRange(3)) {
          // Find the end of the target tiles that are covered by this pixel
          val targetPixelEndRange = Array[Double](sourceX + 1, sourceY + 1)
          sourceToTarget.transform(targetPixelEndRange, 0, targetPixelEndRange, 0, 1)
          if (sourceTile.isDefined(sourceX, sourceY)) {
            emptyTile = false
            // Source pixel is defined. Read it and copy it to all matching target pixels
            val accumulate = new Array[Float](numIntermediateValues)
            accumulator(accumulate, sourceTile.getPixelValue(sourceX, sourceY))
            // The -0.5 is to include up-to the last pixel with a center in the transformed range
            for (targetY <- (targetPixelY1 max targetTile.y1) to ((targetPixelEndRange(1) - 0.5).toInt min targetTile.y2);
                 targetX <- (targetPixelX1 max targetTile.y1) to ((targetPixelEndRange(0) - 0.5).toInt min targetTile.x2)) {
              targetTile.setPixelValue(targetX, targetY, accumulate)
            }
          }
          // Move to the next pixel
          sourceX += 1
          // Update the target pixel. Note: This is only possible for non-shear affine transforms
          targetPixelX1 = (targetPixelEndRange(0) + 0.5).toInt
          if (sourceX > sourcePixelRange(2)) {
            // Reached the end of this line, move to the next line
            sourceX = sourcePixelRange(0).toInt
            sourceY += 1
            // Note: The following two lines are only possible for non-shear affine transforms
            targetPixelX1 = allTargetPixelRange(0).toInt
            targetPixelY1 = (targetPixelEndRange(1) + 0.5).toInt
          }
        }
        if (emptyTile)
          (targetTileID, null)
        else
          (targetTileID, targetTile)
      }

      // Create intermediate tiles when the transformation is simple and a target pixel is bigger than a source one
      // In this case, one source tile can contain many source pixels an they should be accumulated
      val createIntermediateTilesSimpleTargetPixelBigger: Int => (Int, MemoryTile[Array[Float]]) = targetTileID => {
        var emptyTile = true
        val targetTile = new MemoryTile[Array[Float]](targetTileID, targetMetadata, sourceTile.rasterFeature)
        // An inclusive range of all target pixels that will be calculated for this tile
        val allTargetPixelRange = Array[Double](
          targetTile.x1 max targetRasterX1, targetTile.y1 max targetRasterY1,
          targetTile.x2 min targetRasterX2, targetTile.y2 min targetRasterY2
        )
        // The first source pixel that matches the current target pixel
        val sourcePixelRange = new Array[Double](4)
        targetToSource.transform(allTargetPixelRange, 0, sourcePixelRange, 0, 1)
        sourcePixelRange(0) = sourcePixelRange(0).toInt max sourceTile.x1
        sourcePixelRange(1) = sourcePixelRange(1).toInt max sourceTile.y1
        var targetX: Int = allTargetPixelRange(0).toInt
        var targetY: Int = allTargetPixelRange(1).toInt
        while (targetX <= allTargetPixelRange(2) && targetY <= allTargetPixelRange(3)) {
          // Find the end of the source pixels that cover this target pixel
          sourcePixelRange(2) = targetX + 1
          sourcePixelRange(3) = targetY + 1
          targetToSource.transform(sourcePixelRange, 2, sourcePixelRange, 2, 1)
          // The -0.5 in the following condition is to ensure that we include up-to the last source pixel
          // with a center in the transformed range
          sourcePixelRange(2) = (sourcePixelRange(2) - 0.5).toInt min sourceTile.x2
          sourcePixelRange(3) = (sourcePixelRange(3) - 0.5).toInt min sourceTile.y2
          // Loop over all source pixels until finding the first non-empty pixel
          var sourceX: Int = sourcePixelRange(0).toInt
          var sourceY: Int = sourcePixelRange(1).toInt
          val accumulate = new Array[Float](numIntermediateValues)
          while (sourceX <= sourcePixelRange(2) && sourceY <= sourcePixelRange(3)) {
            if (sourceTile.isDefined(sourceX, sourceY))
              accumulator(accumulate, sourceTile.getPixelValue(sourceX, sourceY))
            sourceX += 1
            if (sourceX > sourcePixelRange(2)) {
              sourceX = sourcePixelRange(0).toInt
              sourceY += 1
            }
          }
          if (accumulate.last > 0) {
            emptyTile = false
            targetTile.setPixelValue(targetX, targetY, accumulate)
          }
          // Advance to the next pixel
          targetX += 1
          // Move the box that covers source pixels.
          // Notice that this statement is only valid for non-shear affine transformations.
          sourcePixelRange(0) = sourcePixelRange(2).toInt + 1
          if (targetX > allTargetPixelRange(2)) {
            // Move to the next line
            targetX = allTargetPixelRange(0).toInt
            targetY += 1
            // Move the box that covers source pixels.
            // Notice that this statement is only valid for non-shear affine transformations.
            targetToSource.transform(allTargetPixelRange, 0, sourcePixelRange, 0, 1)
            sourcePixelRange(0) = sourcePixelRange(0).toInt max sourceTile.x1
            sourcePixelRange(1) = sourcePixelRange(3).toInt + 1
          }
        }
        if (emptyTile)
          (targetTileID, null)
        else
          (targetTileID, targetTile)
      }

      // The simplest version where there is a one-to-one mapping between source and target pixels
      val createIntermediateTilesOneToOne: Int => (Int, MemoryTile[Array[Float]]) = targetTileID => {
        var emptyTile = true
        val targetTile = new MemoryTile[Array[Float]](targetTileID, targetMetadata, sourceTile.rasterFeature)
        // An inclusive range of all target pixels that will be calculated for this tile
        val targetX1: Int = targetTile.x1 max targetRasterX1
        val targetY1: Int = targetTile.y1 max targetRasterY1
        val targetX2: Int = targetTile.x2 min targetRasterX2
        val targetY2: Int = targetTile.y2 min targetRasterY2
        // The first source pixel that matches the current target pixel
        val sourcePixelRange = new Array[Double](4)
        targetToSource.transform(Array[Double](targetX1, targetY1, targetX2, targetY2), 0, sourcePixelRange, 0, 2)
        val sourceX1: Int = sourcePixelRange(0).toInt max sourceTile.x1
        val sourceY1: Int = sourcePixelRange(1).toInt max sourceTile.y1
        val sourceX2: Int = sourcePixelRange(2).toInt min sourceTile.x2
        val sourceY2: Int = sourcePixelRange(3).toInt min sourceTile.y2
        var sourceX: Int = sourceX1
        var sourceY: Int = sourceY1
        var targetX: Int = targetX1
        var targetY: Int = targetY1
        while (sourceX <= sourceX2 && sourceY <= sourceY2) {
          if (sourceTile.isDefined(sourceX, sourceY)) {
            val accumulate = new Array[Float](numIntermediateValues)
            accumulator(accumulate, sourceTile.getPixelValue(sourceX, sourceY))
            targetTile.setPixelValue(targetX, targetY, accumulate)
            emptyTile = false
          }
          sourceX += 1
          targetX += 1
          if (sourceX > sourceX2) {
            sourceX = sourceX1
            targetX = targetX1
            sourceY += 1
            targetY += 1
          }
        }

        if (emptyTile)
          (targetTileID, null)
        else
          (targetTileID, targetTile)
      }

      if (targetRasterX1 >= targetRasterX2 || targetRasterY1 >= targetRasterY2) {
        // Empty result. Return empty array
        Seq[(Int, MemoryTile[Array[Float]])]().iterator
      } else {
        // Compute the range of tiles that contain all target tiles. This range is *inclusive*
        val tileCol1 = (targetRasterX1 - targetMetadata.x1) / targetMetadata.tileWidth
        val tileCol2 = (targetRasterX2 - 1 - targetMetadata.x1) / targetMetadata.tileWidth
        val tileRow1 = (targetRasterY1 - targetMetadata.y1) / targetMetadata.tileHeight
        val tileRow2 = (targetRasterY2 - 1 - targetMetadata.y1) / targetMetadata.tileHeight
        // Create an iterator over all target tile IDs
        val targetTileIDs: Iterator[Int] = for (tileRow <- (tileRow1 to tileRow2).iterator;
                                 tileCol <- (tileCol1 to tileCol2).iterator)
          yield tileRow * targetMetadata.numTilesX + tileCol

        // Choose the most efficient creation method based on the transformation
        val simpleTransform = sourceToTarget.isInstanceOf[AffineTransform] &&
          sourceToTarget.asInstanceOf[AffineTransform].getShearX == 0 &&
          sourceToTarget.asInstanceOf[AffineTransform].getShearY == 0
        val creationFunction = if (simpleTransform &&
          sourceToTarget.asInstanceOf[AffineTransform].getScaleX.abs == 1.0 &&
          sourceToTarget.asInstanceOf[AffineTransform].getScaleY.abs == 1.0)
          createIntermediateTilesOneToOne
        else if (simpleTransform && sourceToTarget.asInstanceOf[AffineTransform].getScaleX >= 1)
        // An affine transform with no shearing where a source pixel is bigger than a target pixel
          createIntermediateTilesSimpleSourcePixelBigger
        else if (simpleTransform && sourceToTarget.asInstanceOf[AffineTransform].getScaleX <= 1)
        // An affine transform with no shearing where a target pixel is bigger than a source pixel
          createIntermediateTilesSimpleTargetPixelBigger
        else
        // None of the above, choose the least efficient but most general method
          createIntermediateTilesGeneral
        val interTiles: Iterator[(Int, MemoryTile[Array[Float]])] = targetTileIDs.map(creationFunction)
        interTiles.filter(_._2 != null)
      }
    })
    val numTargetPartitions = if (_numPartitions == 0) raster.getNumPartitions else _numPartitions
    val partitioner = new HashPartitioner(numTargetPartitions)
    // Merge non-empty pixels from intermediate tiles
    intermediateTiles.reduceByKey(partitioner, (t1, t2) => {
      for (y <- t2.y1 to t2.y2; x <- t2.x1 to t2.x2) {
        if (t2.isDefined(x, y)) {
          if (!t1.isDefined(x, y))
            t1.setPixelValue(x, y, t2.getPixelValue(x, y))
          else {
            // The pixel is defined in both, sum the intermediate values
            val v1: Array[Float] = t1.getPixelValue(x, y)
            val v2: Array[Float] = t2.getPixelValue(x, y)
            for (i <- v2.indices)
              v1(i) += v2(i)
            t1.setPixelValue(x, y, v1)
          }
        }
      }
      t1
    }).map(t => {
      // Compute the average of each pixel
      val intermediateTile = t._2
      val finalTile = new MemoryTile[T](t._1, intermediateTile.rasterMetadata, intermediateTile.rasterFeature)
      val computeAverage: Array[Float] => T = averageComputer(finalTile.pixelType).asInstanceOf[Array[Float] => T]
      for ((x, y) <- finalTile.pixelLocations) {
        if (intermediateTile.isDefined(x, y))
          finalTile.setPixelValue(x, y, computeAverage(intermediateTile.getPixelValue(x, y)))
      }
      finalTile.asInstanceOf[ITile[T]]
    })
  }

def reshapeBilinear[T: ClassTag](raster: RasterRDD[T], targetMetadataConv: RasterMetadata => RasterMetadata,
                             numPartitions: Int = 0): RasterRDD[T] = {
    val intermediateReshapedTiles: RDD[(Int, ReshapeTile[T])] = raster.flatMap(sourceTile => {
      val targetMetadata = targetMetadataConv(sourceTile.rasterMetadata)
      val allTargetTiles = ReshapeTile.getTargetTilesForSourceTiles(sourceTile.tileID, targetMetadata, sourceTile.rasterMetadata)
      allTargetTiles.map(targetTileID => {
        val reshapeTile = new ReshapeTile[T](targetTileID, targetMetadata, sourceTile.rasterFeature)
        reshapeTile.addTile(sourceTile)
        (targetTileID, reshapeTile)
      })
    })
    intermediateReshapedTiles.reduceByKey((interTile1, interTile2) => interTile1.merge(interTile2))
      .map(x => x._2.resultTile)
  }

def reshapeNN[T: ClassTag](raster: RasterRDD[T], targetMetadataConv: RasterMetadata => RasterMetadata,
                             numPartitions: Int = 0): RasterRDD[T] = {
    // A localized cache in each executor to avoid creating the source <-> target transforms for each tile
    val cache = new mutable.HashMap[Int, (MathTransform, MathTransform)]()

    val intermediateTiles: RDD[(Int, MemoryTile[T])] = raster.flatMap(sourceTile => {
      val targetMetadata: RasterMetadata = targetMetadataConv(sourceTile.rasterMetadata)
      // We need a transformer that transforms a pixel in source to the target pixel in target and vice-versa
      // These are the steps needed to transform from source to target:
      // 1- Use source metadata grid-to-model to convert from source raster space to source model space
      // 2- Use CRS transformation to transform from source model space to target model space
      // 3- Use target metadata model-to-grid to convert from target model space to target grid space
      // To do all these steps efficiently, we concatenate all these transformations into one
      val (sourceToTarget, targetToSource) = cache.getOrElseUpdate(sourceTile.rasterMetadata.srid, {
        val sourceG2M = new AffineTransform2D(sourceTile.rasterMetadata.g2m)
        val transformationInfo: Reprojector.TransformationInfo =
          Reprojector.findTransformationInfo(sourceTile.rasterMetadata.srid, targetMetadata.srid)
        val targetM2G = new AffineTransform2D(targetMetadata.g2m).inverse()
        val sourceToTarget: MathTransform = concatenateTransforms(sourceG2M, transformationInfo.sourceSnap,
          transformationInfo.mathTransform, targetM2G)
        val targetToSource: MathTransform = sourceToTarget.inverse()
        (sourceToTarget, targetToSource)
      })

      // First, convert the bounding box of the entire source tile to know the range of target tiles
      val tileCorners = Array[Double](sourceTile.x1, sourceTile.y1,
        sourceTile.x2 + 1, sourceTile.y1,
        sourceTile.x2 + 1, sourceTile.y2 + 1,
        sourceTile.x1, sourceTile.y2 + 1,
      )
      sourceToTarget.transform(tileCorners, 0, tileCorners, 0, 4)
      // Convert to a range of pixels in the target. This range is *exclusive*
      // The target range contains all pixels whose centers are in the converted range
      val targetRasterX1: Int = (((tileCorners(0) min tileCorners(2) min tileCorners(4) min tileCorners(6))+0.5) max targetMetadata.x1).toInt
      val targetRasterX2: Int = (((tileCorners(0) max tileCorners(2) max tileCorners(4) max tileCorners(6))+0.5) min targetMetadata.x2).toInt
      val targetRasterY1: Int = (((tileCorners(1) min tileCorners(3) min tileCorners(5) min tileCorners(7))+0.5) max targetMetadata.y1).toInt
      val targetRasterY2: Int = (((tileCorners(1) max tileCorners(3) max tileCorners(5) max tileCorners(7))+0.5) min targetMetadata.y2).toInt

      val createIntermediateTilesNN: Int => (Int, MemoryTile[T]) = targetTileID => {
        var emptyTile = true
        val targetTile = new MemoryTile[T](targetTileID, targetMetadata, sourceTile.rasterFeature)
        // (x1,y1)-(x2,y2) is an inclusive range of target pixels that match with this tile
        val targetTileX1 = targetTile.x1 max targetRasterX1
        val targetTileX2 = targetTile.x2 min targetRasterX2
        val targetTileY1 = targetTile.y1 max targetRasterY1
        val targetTileY2 = targetTile.y2 min targetRasterY2
        for (targetY <- targetTileY1 to targetTileY2; targetX <- targetTileX1 to targetTileX2) {
          // Project the center of the target pixel to the source
          val sourcePixel = Array[Double](targetX + 0.5, targetY + 0.5)
          targetToSource.transform(sourcePixel, 0, sourcePixel, 0, 1)
          val sourceX: Int = sourcePixel(0).toInt
          val sourceY: Int = sourcePixel(1).toInt
          if (sourceX >= sourceTile.x1 && sourceX <= sourceTile.x2 &&
            sourceY >= sourceTile.y1 && sourceY <= sourceTile.y2 && sourceTile.isDefined(sourceX, sourceY)) {
            emptyTile = false
            targetTile.setPixelValue(targetX, targetY, sourceTile.getPixelValue(sourceX, sourceY))
          }
        }
        if (emptyTile) (targetTileID, null) else (targetTileID, targetTile)
      }
      if (targetRasterX1 >= targetRasterX2 || targetRasterY1 >= targetRasterY2) {
        // Empty result. Return empty array
        Seq[(Int, MemoryTile[T])]().iterator
      } else {
        // Compute the range of tiles that contain all target tiles. This range is *inclusive*
        val tileCol1 = (targetRasterX1 - targetMetadata.x1) / targetMetadata.tileWidth
        val tileCol2 = (targetRasterX2 - 1 - targetMetadata.x1) / targetMetadata.tileWidth
        val tileRow1 = (targetRasterY1 - targetMetadata.y1) / targetMetadata.tileHeight
        val tileRow2 = (targetRasterY2 - 1 - targetMetadata.y1) / targetMetadata.tileHeight
        // Create an iterator over all target tile IDs
        val targetTileIDs: Iterator[Int] = for (tileRow <- (tileRow1 to tileRow2).iterator;
                                                tileCol <- (tileCol1 to tileCol2).iterator)
        yield tileRow * targetMetadata.numTilesX + tileCol

        val interTiles: Iterator[(Int, MemoryTile[T])] = targetTileIDs.map(createIntermediateTilesNN)
        interTiles.filter(_._2 != null)
      }
    })

    val numTargetPartitions: Int = if (numPartitions == 0) raster.getNumPartitions else numPartitions
    val partitioner = new HashPartitioner(numTargetPartitions)
    intermediateTiles.reduceByKey(partitioner, (t1, t2) => {
      for ((x, y) <- t2.pixelLocations) {
        if (t2.isDefined(x, y))
          t1.setPixelValue(x, y, t2.getPixelValue(x, y))
      }
      t1
    }).map(_._2.asInstanceOf[ITile[T]])
  }

def reproject[T: ClassTag](raster: RasterRDD[T], targetCRS: CoordinateReferenceSystem, unifiedRaster: Boolean = false,
                             interpolationMethod: InterpolationMethod.InterpolationMethod =
                             InterpolationMethod.NearestNeighbor): RasterRDD[T] = {
    val targetMetadata: RasterMetadata => RasterMetadata = if (!unifiedRaster) {
      _.reproject(targetCRS)
    } else {
      val unifiedMetadata = RasterMetadata.reproject(RasterMetadata.allMetadata(raster), targetCRS)
      logInfo(s"Reprojecting with unified metadata ${unifiedMetadata}")
      _ => unifiedMetadata
    }
    interpolationMethod match {
      case InterpolationMethod.Average => reshapeAverage(raster, targetMetadata)
      case InterpolationMethod.NearestNeighbor => reshapeNN(raster, targetMetadata)
    }
  }

def rescale[T: ClassTag](raster: RasterRDD[T], rasterWidth: Int, rasterHeight: Int, unifiedRaster: Boolean = false,
                           interpolationMethod: InterpolationMethod.InterpolationMethod =
                           InterpolationMethod.NearestNeighbor): RasterRDD[T] = {
    val targetMetadata: RasterMetadata => RasterMetadata = if (!unifiedRaster) {
      _.rescale(rasterWidth, rasterHeight)
    } else {
      val unifiedMetadata = RasterMetadata.rescale(RasterMetadata.allMetadata(raster), rasterWidth, rasterHeight)
      logInfo(s"Rescaling with unified metadata ${unifiedMetadata}")
      _ =>  unifiedMetadata
    }
    interpolationMethod match {
      case InterpolationMethod.Average => reshapeAverage(raster, targetMetadata)
      case InterpolationMethod.NearestNeighbor => reshapeNN(raster, targetMetadata)
    }
  }

def retile[T: ClassTag](raster: RasterRDD[T], tileWidth: Int, tileHeight: Int): RasterRDD[T] = {
    // Notice that for retile, there is a one-to-one correspondence in pixels so we use the more efficient NN method
    reshapeNN(raster, _.retile(tileWidth, tileHeight))
  }

override def getPixelValue(i: Int, j: Int): T = {
      assert(existingTile.isPixelInRange(i + dx, j + dy), s"Pixel out of range ($i,$j) of tile ${this}")
      existingTile.getPixelValue(i + dx, j + dy)
    }

override def isEmpty(i: Int, j: Int): Boolean = {
      assert(existingTile.isPixelInRange(i + dx, j + dy), s"Pixel out of range ($i,$j) of tile ${this}")
      existingTile.isEmpty(i + dx, j + dy)
    }

def divideScene[T: ClassTag](raster: RasterRDD[T], targetMetadata: RasterMetadata, numTilesX: Int, numTilesY: Int):
    RasterRDD[T] ={
    val targetNumPartitions: Int = math.min(raster.getNumPartitions, targetMetadata.numTiles / numTilesX / numTilesY)
    val resultRDD = reshapeNN(raster, _ => targetMetadata, targetNumPartitions)
    resultRDD.map(tile => {
      // All tiles must be on the same target metadata
      assert(tile.rasterMetadata == targetMetadata)
      // Change the Metadata and tile ID of this tile to make it part of a subgroup
      val tileX = tile.tileID % targetMetadata.numTilesX
      val tileY = tile.tileID / targetMetadata.numTilesX
      // Find the position of the top-left tile in the same partition (inclusive)
      val tile1X = tileX - (tileX % numTilesX)
      val tile1Y = tileY - (tileY % numTilesY)

      // Create the new metadata
      val newX1 = 0
      val newY1 = 0
      val newX2 = (((tile1X + numTilesX) * targetMetadata.tileWidth) min targetMetadata.x2) - (tile1X * targetMetadata.tileWidth)
      val newY2 = (((tile1Y + numTilesY) * targetMetadata.tileHeight) min targetMetadata.y2) - (tile1Y * targetMetadata.tileHeight)
      val newG2M = new AffineTransform(targetMetadata.g2m)
      newG2M.concatenate(AffineTransform.getTranslateInstance(tile1X * targetMetadata.tileWidth, tile1Y * targetMetadata.tileHeight))
      val newMetadata = new RasterMetadata(newX1, newY1, newX2, newY2, targetMetadata.tileWidth, targetMetadata.tileHeight,
        targetMetadata.srid, newG2M)

      new ReTile[T](tile, newMetadata)
    })
  }

def slidingWindow2[T: ClassTag, U: ClassTag](raster: RasterRDD[T], w: Int, winFunc: (Array[T], Array[Boolean]) => U):
  RasterRDD[U] = {
    assert(RasterMetadata.allMetadata(raster).length == 1,
      "Raster input to window calculation function cannot have mixed metadata")
    val intermediateTiles: RDD[(Int, SlidingWindowTile[T, U])] = raster.flatMap(sourceTile => {
      val affectedTiles: Array[Int] = SlidingWindowTile.getTilesInWindow(sourceTile.tileID, sourceTile.rasterMetadata, w)
      affectedTiles.iterator.map(tid => {
        val wt = new SlidingWindowTile(tid, sourceTile.rasterMetadata, sourceTile.rasterFeature, w, winFunc)
        wt.addTile(sourceTile)
        (wt.tileID, wt)
      })
    })
    val partitioner: Partitioner = if (raster.partitioner.isEmpty || raster.getNumPartitions < raster.sparkContext.defaultParallelism)
      new HashPartitioner(raster.sparkContext.defaultParallelism) else raster.partitioner.get
    intermediateTiles.reduceByKey(partitioner, (wt1, wt2) => wt1.merge(wt2))
      .map(x => x._2.resultTile)
  }

def slidingWindow[T: ClassTag, U: ClassTag](raster: RasterRDD[T], w: Int, f: (Array[T], Array[Boolean]) => U):
    RasterRDD[U] = {
    import RaptorMixin._
    assert(raster.allMetadata.length == 1, "Raster input to window calculation function cannot have mixed metadata")
    val numValues = (2 * w + 1) * (2 * w + 1)
    val intermediateTiles: RDD[(Int, MemoryTileWindow[T])] = raster.flatMap(sourceTile => {
      val metadata = sourceTile.rasterMetadata
      // Compute the window of pixels that will be affected by current tile *inclusive*
      val windowX1 = (sourceTile.x1 - w) max metadata.x1
      val windowY1 = (sourceTile.y1 - w) max metadata.y1
      val windowX2 = (sourceTile.x2 + w) min (metadata.x2 - 1)
      val windowY2 = (sourceTile.y2 + w) min (metadata.y2 - 1)
      // Compute the *inclusive* range of tiles that will be affected by current tile
      val tileCol1 = (windowX1 - metadata.x1) / metadata.tileWidth
      val tileCol2 = (windowX2 - metadata.x1) / metadata.tileWidth
      val tileRow1 = (windowY1 - metadata.y1) / metadata.tileHeight
      val tileRow2 = (windowY2 - metadata.y1) / metadata.tileHeight
      // Create an array of all target tile IDs
      val targetTileIDs = new Array[Int]((tileCol2 - tileCol1 + 1) * (tileRow2 - tileRow1 + 1))
      var i = 0
      for (tileRow <- tileRow1 to tileRow2; tileCol <- tileCol1 to tileCol2) {
        targetTileIDs(i) = tileRow * metadata.numTilesX + tileCol
        i += 1
      }
      // Now, compute the target tiles and return them
      targetTileIDs.iterator.map(targetTileID => {
        val targetTile = MemoryTileWindow.create[T](targetTileID, metadata, sourceTile.rasterFeature, numValues)
        // Calculate the source *inclusive* range of pixels that might affect this tile
        val sourceX1 = (metadata.getTileX1(targetTileID) - w) max sourceTile.x1
        val sourceY1 = (metadata.getTileY1(targetTileID) - w) max sourceTile.y1
        val sourceX2 = (metadata.getTileX2(targetTileID) + w) min sourceTile.x2
        val sourceY2 = (metadata.getTileY2(targetTileID) + w) min sourceTile.y2
        for (sourceY <- sourceY1 to sourceY2; sourceX <- sourceX1 to sourceX2) {
          if (sourceTile.isDefined(sourceX, sourceY)) {
            val value = sourceTile.getPixelValue(sourceX, sourceY)
            val targetX1 = (sourceX - w) max metadata.getTileX1(targetTileID)
            val targetY1 = (sourceY - w) max metadata.getTileY1(targetTileID)
            val targetX2 = (sourceX + w) min metadata.getTileX2(targetTileID)
            val targetY2 = (sourceY + w) min metadata.getTileY2(targetTileID)
            for (targetY <- targetY1 to targetY2; targetX <- targetX1 to targetX2) {
              val dx = targetX - sourceX
              val dy = targetY - sourceY
              val position = (2 * w + 1) * (dy + w) + dx + w
              targetTile.setValue(targetX, targetY, position, value)
            }
          }
        }
        (targetTileID, targetTile)
      })
    })

    // Merge all values from intermediate tiles
    val finalWindowTiles: RDD[(Int, MemoryTileWindow[T])] = intermediateTiles.reduceByKey((t1, t2) => {
      t1.mergeWith(t2)
      t1
    })
    // Apply the user-defined function to calculate the final tile
    finalWindowTiles.map(windowTile => {
      val finalTile = new MemoryTile[U](windowTile._1, windowTile._2.metadata, windowTile._2.rasterFeature)
      val values: Array[T] = new Array[T](numValues)
      val defined: Array[Boolean] = new Array[Boolean](numValues)
      for (y <- finalTile.y1 to finalTile.y2; x <- finalTile.x1 to finalTile.x2) {
        val count = windowTile._2.readValues(x, y, values, defined)
        if (count > 0)
          finalTile.setPixelValue(x, y, f(values, defined))
      }
      finalTile
    })
  }

def rasterizePixels[T: ClassTag](pixels: RDD[(Int, Int, T)], metadata: RasterMetadata, rasterFeature: RasterFeature): RasterRDD[T] = {
    val pixelsAssignedToTiles: RDD[(Int, (Int, Int, T))] = pixels.map(p => {
      val tileID = metadata.getTileIDAtPixel(p._1, p._2)
      (tileID, p)
    })
    pixelsAssignedToTiles.groupByKey().map(t => {
      val tile = new MemoryTile[T](t._1, metadata, rasterFeature)
      for (p <- t._2)
        tile.setPixelValue(p._1, p._2, p._3)
      tile
    })
  }

def rasterizePoints[T: ClassTag](points: RDD[(Double, Double, T)], metadata: RasterMetadata, rasterFeature: RasterFeature): RasterRDD[T] = {
    rasterizePixels(points.map(p => {
      val geolocation = Array(p._1, p._2)
      metadata.g2m.inverseTransform(geolocation, 0, geolocation, 0, 1)
      (geolocation(0).toInt, geolocation(1).toInt, p._3)
    }), metadata, rasterFeature)
  }

def flatten[T](raster: RasterRDD[T]): RDD[(Int, Int, RasterMetadata, T)] = {
    raster.flatMap(tile => {
      for (y <- tile.y1 to tile.y2 iterator; x <- tile.x1 to tile.x2 iterator; if tile.isDefined(x, y))
        yield (x, y, tile.rasterMetadata, tile.getPixelValue(x, y))
    })
  }

def overlay[T: ClassTag, V](@varargs inputs: RDD[ITile[T]]*)
                                               (implicit v: ClassTag[V]): RasterRDD[Array[V]] = {
    val inputsByID: Seq[RDD[(Int, ITile[T])]] = inputs.map(i => i.map(t => (t.tileID, t)))
    val partitioner = Partitioner.defaultPartitioner(inputsByID.head, inputsByID:_*)
    val grouped: CoGroupedRDD[Int] = new CoGroupedRDD(inputsByID, partitioner)
    grouped.map(ts => {
      val tiles: Array[ITile[T]] = ts._2.flatMap(x => x.map(_.asInstanceOf[ITile[T]]))
      new StackedTile[V](tiles:_*)
    })
  }

def addTile(tile: ITile[T]): Unit = {
    inputTiles.append(tile)
  }

def merge(other: ReshapeTile[T]): ReshapeTile[T] = {
    for (t <- other.inputTiles; if t != null)
      addTile(t)
    this
  }

def resultTile: ITile[T] = {
    val tile = new MemoryTile[T](tileID, targetMetadata, rasterFeature)
    val averageComputer: ReshapeTile.AverageComputerFunction[Any] = Computers(tile.pixelType)
    val sourceMetadata = inputTiles.map(_.rasterMetadata).distinct
    val values = new Array[T](targetMetadata.tileWidth * targetMetadata.tileHeight)
    val counts = new Array[Int](targetMetadata.tileWidth * targetMetadata.tileHeight)
    val targetToSourceGrid = sourceMetadata.map(m => RasterMetadata.gridToGridTransform(targetMetadata, m))
    for (y <- targetMetadata.getTileY1(tileID) to targetMetadata.getTileY2(tileID);
         x <- targetMetadata.getTileX1(tileID) to targetMetadata.getTileX2(tileID)) {
      // Map the center of the target pixel to every source raster
      val targetPointLocation = Array[Float](x + 0.5f, y + 0.5f)
      // Try with one source metadata at a time until we find a matching tile
      // TODO: Consider the case of one pixel falling between two metadata, i.e., two source files
      for (iMetadata <- sourceMetadata.indices) {
        val sourcePointLocation = new Array[Float](2)
        targetToSourceGrid(iMetadata).transform(targetPointLocation, 0, sourcePointLocation, 0, 1)
        val sourceTileID = sourceMetadata(iMetadata).getTileIDAtPixel(sourcePointLocation(0).toInt, sourcePointLocation(1).toInt)
        // Check if we have this tile
        val sourceTileO: Option[ITile[T]] = inputTiles.find(t => t.tileID == sourceTileID && t.rasterMetadata == sourceMetadata(iMetadata))
        if (sourceMetadata(iMetadata).isPixelInRange(sourcePointLocation(0).toInt, sourcePointLocation(1).toInt) &&  sourceTileO.isDefined) {
          val sourceTile = sourceTileO.get
          val sourceValues = new Array[T](4)
          val sourcePixelExists = new Array[Boolean](4)
          // Check if we can find all four surrounding points within this tile. This will be true for most cases
          if (sourceMetadata(iMetadata).getTileX2(sourceTileID) - sourcePointLocation(0) > 1.0 &&
            sourceMetadata(iMetadata).getTileY2(sourceTileID) - sourcePointLocation(1) > 1.0) {
            // Can compute the target pixel value entirely from this pixel
            // Retrieve the four pixels that surround where the mapping landed
            var i = 0
            for (dy <- Array(0, 1); dx <- Array(0, +1)) {
              val xx: Int = sourcePointLocation(0).toInt + dx
              val yy: Int = sourcePointLocation(1).toInt + dy
              assert(sourceTile.isPixelInRange(xx, yy),
                s"Unexpected out-of-bound pixel with the simple case $xx $yy in tile $sourceTile, sourcePointLocation: ${sourcePointLocation.mkString(",")}")
              sourcePixelExists(i) = sourceTile.isDefined(xx, yy)
              if (sourcePixelExists(i))
                sourceValues(i) = sourceTile.getPixelValue(xx, yy)
              i += 1
            }
          } else {
            // Map each corner point to find up-to four tiles for the surrounding pixels
            // Retrieve the four pixels that surround where the target pixel maps in source raster
            var i = 0
            for (dy <- Array(0, 1); dx <- Array(0, +1)) {
              val xx: Int = sourcePointLocation(0).toInt + dx
              val yy: Int = sourcePointLocation(1).toInt + dy
              val sourceTileID = sourceMetadata(iMetadata).getTileIDAtPixel(xx, yy)
              val sourceTileO: Option[ITile[T]] = inputTiles.find(t => t.tileID == sourceTileID && t.rasterMetadata == sourceMetadata(iMetadata))
              if (sourceTileO.isDefined) {
                sourcePixelExists(i) = sourceTileO.get.isDefined(xx, yy)
                if (sourcePixelExists(i))
                  sourceValues(i) = sourceTileO.get.getPixelValue(xx, yy)
                i += 1
              }
            }
          }
          // Now, given the four values, apply the bilinear function by average the values horizontally,
          // and then averaging the two averages vertically
          // Since some pixels might be undefined, we will ignore them in average calculation
          val xRatio: Float = sourcePointLocation(0) - sourcePointLocation(0).toInt
          val yRatio: Float = sourcePointLocation(1) - sourcePointLocation(1).toInt
          val average1: T = if (sourcePixelExists(0) && sourcePixelExists(1))
            averageComputer(sourceValues(0), sourceValues(1), xRatio).asInstanceOf[T]
          else if (sourcePixelExists(0))
            sourceValues(0)
          else
            sourceValues(1)
          val average1Exists = sourcePixelExists(0) || sourcePixelExists(1)
          val average2: T = if (sourcePixelExists(2) && sourcePixelExists(3))
            averageComputer(sourceValues(2), sourceValues(3), xRatio).asInstanceOf[T]
          else if (sourcePixelExists(2))
            sourceValues(2)
          else
            sourceValues(3)
          val average2Exists = sourcePixelExists(2) || sourcePixelExists(3)
          val finalValue: T = if (average1Exists && average2Exists)
            averageComputer(average1, average2, yRatio).asInstanceOf[T]
          else if (average1Exists)
            average1
          else
            average2
          if (average1Exists || average2Exists) {
            val offset: Int = (y - targetMetadata.getTileY1(tileID)) * targetMetadata.tileWidth +
              (x - targetMetadata.getTileX1(tileID))
            if (counts(offset) == 0)
              values(offset) = finalValue
            else
              values(offset) = averageComputer(values(offset), finalValue, 1.0f).asInstanceOf[T]
            counts(offset) += 1
          }
        }
      }
    }
    // Use the values to fill in the table
    for (y <- tile.y1 to tile.y2; x <- tile.x1 to tile.x2) {
      val offset = (y - tile.y1) * tile.tileWidth + (x - tile.x1)
      if (counts(offset) > 0) {
        // Compute the final value as values(offset) / counts(offset)
        tile.setPixelValue(x, y, averageComputer(values(offset), values(offset), counts(offset) / 2.0f).asInstanceOf[T])
      }
    }
    tile
  }

def getTargetTilesForSourceTiles(sourceTileID: Int, targetMetadata: RasterMetadata, sourceMetadata: RasterMetadata): Array[Int] = {
    val sourceCornerPoints: Array[Double] = Array[Double](
      sourceMetadata.getTileX1(sourceTileID) - 1, sourceMetadata.getTileY1(sourceTileID) - 1,
      sourceMetadata.getTileX2(sourceTileID) + 1, sourceMetadata.getTileY1(sourceTileID) - 1,
      sourceMetadata.getTileX2(sourceTileID) + 1, sourceMetadata.getTileY2(sourceTileID) + 1,
      sourceMetadata.getTileX1(sourceTileID) - 1, sourceMetadata.getTileY2(sourceTileID) + 1,
    )
    val sourceGtoTargetG: MathTransform = RasterMetadata.gridToGridTransform(sourceMetadata, targetMetadata)
    val targetCornerPoints: Array[Double] = new Array[Double](8)
    sourceGtoTargetG.transform(sourceCornerPoints, 0, targetCornerPoints, 0, 4)

    val xs = Array[Double](targetCornerPoints(0), targetCornerPoints(2), targetCornerPoints(4), targetCornerPoints(6))
    val ys = Array[Double](targetCornerPoints(1), targetCornerPoints(3), targetCornerPoints(5), targetCornerPoints(7))
    val minX: Int = xs.min.floor.toInt
    val maxX: Int = xs.max.ceil.toInt
    val minY: Int = ys.min.floor.toInt
    val maxY: Int = ys.max.ceil.toInt
    var x = minX
    var y = minY
    var results = Array[Int]()
    while (y <= maxY && x <= maxX) {
      if (x >= targetMetadata.x1 && x < targetMetadata.x2 && y >= targetMetadata.y1 && y < targetMetadata.y2) {
        val tid = targetMetadata.getTileIDAtPixel(x, y)
        results = results :+ tid
      }
      x = (x + targetMetadata.tileWidth) / targetMetadata.tileWidth * targetMetadata.tileWidth
      if (x > maxX) {
        x = minX
        y = (y + targetMetadata.tileHeight) / targetMetadata.tileHeight * targetMetadata.tileHeight
      }
    }
    results.distinct
  }

def addTile(tile: ITile[T]): Unit = {
    assert(tileIDToArrayIndex.contains(tile.tileID), s"Unexpected tile #${tile.tileID} while computing tile #$tileID")
    assert(inputTiles(tileIDToArrayIndex(tile.tileID)) == null, s"Duplicate entry for tile #${tile.tileID}")
    assert(_resultTile == null, "Cannot add tiles after computing the final tile")
    inputTiles(tileIDToArrayIndex(tile.tileID)) = tile
    if (!inputTiles.contains(null)) {
      // Already got all expected tiles, do the computation
      computeResultTile()
      // Remove input tiles to reduce memory footprint and speed up serialization
      for (i <- inputTiles.indices)
        inputTiles(i) = null
    }
  }

def merge(other: SlidingWindowTile[T, U]): SlidingWindowTile[T, U] = {
    for (t <- other.inputTiles; if t != null)
      addTile(t)
    this
  }

def resultTile: ITile[U] = {
    computeResultTile()
    _resultTile
  }

def getTilesInWindow(tileID: Int, metadata: RasterMetadata, w: Int): Array[Int] = {
    val minX: Int = metadata.getTileX1(tileID) - w
    val maxX: Int = metadata.getTileX2(tileID) + w
    val minY: Int = metadata.getTileY1(tileID) - w
    val maxY: Int = metadata.getTileY2(tileID) + w
    var x = minX
    var y = minY
    var results = Array[Int]()
    while (y <= maxY && x <= maxX) {
      if (x >= metadata.x1 && x < metadata.x2 && y >= metadata.y1 && y < metadata.y2) {
        val tid = metadata.getTileIDAtPixel(x, y)
        results = results :+ tid
      }
      x = (x + metadata.tileWidth) / metadata.tileWidth * metadata.tileWidth
      if (x > maxX) {
        x = minX
        y = (y + metadata.tileHeight) / metadata.tileHeight * metadata.tileHeight
      }
    }
    results
  }

override def getPixelValue(x: Int, y: Int): Array[T] = {
    val outVal = new Array[T](numComponents)
    var i = 0
    tiles.foreach(tile => tile.getPixelValue(x, y) match {
      case vs: Array[_] =>
        for (v <- vs) {
          outVal(i) = v.asInstanceOf[T]
          i += 1
        }
      case v: Any =>
        outVal(i) = v.asInstanceOf[T]
        i += 1
    })
    outVal
  }

override def isEmpty(i: Int, j: Int): Boolean = {
    for (t <- tiles)
      if (t.isEmpty(i, j))
        return true
    false
  }

override def next: RaptorJoinResultTile[T] = {
    val toReturn = nextTuple
    nextTuple = prefetchNext
    toReturn
  }

override def addDependentClasses(opts: BeastOptions, classes: util.Stack[Class[_]]): Unit = {
    super.addDependentClasses(opts, classes)
    classes.add(classOf[GeoTiffReader[Int]])
  }

override def run(opts: BeastOptions, inputs: Array[String], outputs: Array[String], sc: SparkContext): Unit = {
    sc.hadoopConfiguration.setInt("mapreduce.input.fileinputformat.split.maxsize", 8388608)
    val iLayer = opts.getString(RasterLayer, "0")
    opts.set(IRasterReader.RasterLayerID, iLayer)
    val rasterFile = inputs(1)
    val aggregateFunction = Symbol(opts.getString(AggregateFunction, "aggregates"))
    var vectors: RDD[IFeature] = sc.spatialFile(inputs(0), opts.retainIndex(0))
    if (vectors.getNumPartitions < sc.defaultParallelism) {
      logInfo(s"Repartitioning vector data to ${sc.defaultParallelism} partitions")
      vectors = vectors.repartition(sc.defaultParallelism)
    }
    val collectorClass: Class[_ <: Collector] = aggregateFunction match {
      case 'aggregates => classOf[Statistics]
      case other => throw new RuntimeException(s"Unrecognized aggregate function $other")
    }

    // For profiling, count number of processed tiles
    val numTiles = sc.longAccumulator("NumTiles")
    val results: RDD[(IFeature, Collector)] =
      zonalStats2(vectors, new RasterFileRDD[Int](sc, rasterFile, opts), collectorClass, opts, numTiles)

    // Write results to the output
    val element = results.first()
    val numBands = element._2.getNumBands
    var schemaElements: Seq[StructField] = element._1.schema.filterNot(_.dataType == GeometryDataType)
    if (numBands == 1) {
      schemaElements = schemaElements ++ Seq(StructField("sum", DoubleType), StructField("count", DoubleType),
        StructField("min", DoubleType), StructField("max", DoubleType))
    } else {
      for (b <- 1 to numBands) {
        schemaElements = schemaElements ++ Seq(StructField(s"sum_$b", DoubleType), StructField("count_$b", DoubleType),
          StructField("min_$b", DoubleType), StructField("max_$b", DoubleType))
      }
    }
    val normalizedResults: SpatialRDD = results.filter(fc => fc._2 != null).map(fc => {
      val statistics: Statistics = fc._2.asInstanceOf[Statistics]
      val statValues: Array[Any] = new Array[Any](numBands * 4)
      val statFields: Array[StructField] = new Array[StructField](numBands * 4)
      for (b <- 0 until numBands) {
        val suffix: String = if (numBands == 1) "" else s"_${b}"
        statValues(4 * b + 0) = statistics.sum(b)
        statFields(4 * b + 0) = StructField("sum"+suffix, DoubleType)
        statValues(4 * b + 1) = statistics.count(b)
        statFields(4 * b + 1) = StructField("count"+suffix, DoubleType)
        statValues(4 * b + 2) = statistics.min(b)
        statFields(4 * b + 2) = StructField("min"+suffix, DoubleType)
        statValues(4 * b + 3) = statistics.max(b)
        statFields(4 * b + 3) = StructField("max"+suffix, DoubleType)
      }
      Feature.concat(fc._1, new GenericRowWithSchema(statValues, StructType(statFields)))
    })
    val oFormat = opts.getString(SpatialWriter.OutputFormat, opts.getString(SpatialFileRDD.InputFormat))
    if (opts.get(CSVFeatureWriter.WriteHeader) == null)
      opts.set(CSVFeatureWriter.WriteHeader, true)
    val bo: BeastOptions = opts
    SpatialWriter.saveFeatures(normalizedResults, oFormat, outputs(0), bo)
    logInfo(s"Number of processed tiles in zonal statistics is ${numTiles.value}")
  }

def zonalStats2[T](zones: RDD[IFeature], raster: RDD[ITile[T]], collectorClass: Class[_ <: Collector],
                  opts: BeastOptions, numTiles: LongAccumulator = null)(implicit t: ClassTag[T]): RDD[(IFeature, Collector)] = {
    val conf = zones.sparkContext.getConf
    val rasterSRID = raster.first().rasterMetadata.srid
    // Generate a unique ID for each feature
    val idFeatures: RDD[(Long, IFeature)] = zones
      .reproject(rasterSRID)
      .zipWithUniqueId().map(x => (x._2, x._1))

    // (Feature ID, (x, y, value))
    val featureValue: RDD[(Long, (Int, Int, T))] = RaptorJoin.raptorJoinIDFull(raster, idFeatures, opts, numTiles)
      .map(result => (result.featureID, (result.x, result.y, result.m)))

    // Compute statistics for each feature
    val zeroValue = collectorClass.getConstructor().newInstance()
    zeroValue.setNumBands(1)
    val featureStats: RDD[(Long, Collector)] = featureValue.aggregateByKey(zeroValue)(
      (u: Collector, v: (Int, Int, T)) => u.collect(v._1, v._2, Array[Float](v._3.asInstanceOf[Number].floatValue())),
      (u1: Collector, u2: Collector) => u1.accumulate(u2)
    )

    // Join back with the original features to put back the entire feature and remove the ID
    idFeatures.join(featureStats).map( kv => kv._2)
  }

def zonalStatsLocal[T](geometries: Array[Geometry], raster: IRasterReader[T], collectorClass: Class[_ <: Collector])
                       : Array[Collector] = {
    val joinResults = RaptorJoin.raptorJoinLocal(Array(raster), geometries)
    val constructor = collectorClass.getConstructor()
    val results: Array[Collector] = new Array[Collector](geometries.length)
    joinResults.foreach(result => {
      val m: Array[Float] = result.m match {
        case f: Float => Array(f)
        case f: java.lang.Float => Array(f)
        case i: Integer => Array(i.toFloat)
        case i: Int => Array(i.toFloat)
        case fs: Array[Float] => fs
        case is: Array[Int] => is.map(_.toFloat)
      }
      var collector: Collector = results(result.featureID.toInt)
      if (collector == null) {
        collector = constructor.newInstance()
        collector.setNumBands(m.length)
        results(result.featureID.toInt) = collector
      }
      collector.collect(result.x, result.y, m)
    })
    results
  }

def computeZonalStatisticsNaive[T](geometry: Geometry, raster: IRasterReader[T], result: Collector): Unit = {
    // Find the MBR of the geometry to determine which pixels to read from the raster
    val p: Point2D.Double = new Point2D.Double
    val corner1: Point2D.Double = new Point2D.Double
    val corner2: Point2D.Double = new Point2D.Double
    val mbr = geometry.getEnvelopeInternal
    raster.metadata.modelToGrid(mbr.getMinX, mbr.getMinY, corner1)
    raster.metadata.modelToGrid(mbr.getMaxX, mbr.getMaxY, corner2)
    val i1: Int = Math.max(0, Math.min (corner1.x, corner2.x) ).toInt
    val i2: Int = Math.min(raster.metadata.rasterWidth, Math.ceil (Math.max (corner1.x, corner2.x) ) ).toInt
    val j1: Int = Math.max(0, Math.min (corner1.y, corner2.y) ).toInt
    val j2: Int = Math.min(raster.metadata.rasterHeight, Math.ceil (Math.max (corner1.y, corner2.y) ) ).toInt
    var currentTile: ITile[T] = null
    for (jPixel <- j1 until j2; iPixel <- i1 until i2) {
      raster.metadata.gridToModel(iPixel + 0.5, jPixel + 0.5, p)
      val pointCoords = new CoordinateXY(p.x, p.y)
      if (geometry.contains(geometry.getFactory.createPoint(pointCoords))) {
        val tileID: Int = raster.metadata.getTileIDAtPixel (iPixel, jPixel)
        if (currentTile == null || currentTile.tileID != tileID)
          currentTile = raster.readTile (tileID)
        if (!currentTile.isEmpty(iPixel, jPixel)) {
          val m: Array[Float] = currentTile.getPixelValue(iPixel, jPixel) match {
            case f: Float => Array(f)
            case i: Int => Array(i.toFloat)
            case n: java.lang.Number => Array(n.floatValue())
            case fs: Array[Float] => fs
            case is: Array[Int] => is.map(_.toFloat)
          }
          if (result.getNumBands == 0)
            result.setNumBands(m.length)
          result.collect(iPixel, jPixel, m)
        }
      }
    }
  }

def computeZonalStatisticsNaive[T](geometries: Array[Geometry], raster: IRasterReader[T],
                                     collectorClass: Class[_ <: Collector]): Array[Collector] = {
    val results = new Array[Collector](geometries.length)
    val constructor = collectorClass.getConstructor()
    for (i <- geometries.indices) {
      results(i) = constructor.newInstance()
      computeZonalStatisticsNaive(geometries(i), raster, results(i))
    }
    results
  }

